NAME = 'DaOT1871NT1907: Danish OT1871 + NT1907 with original orthography'
BOOK = 'Joshua'

CHAPTERS = {
    1: {
        1: 'Og det skete efter Mose Herrens Tjeners Død, da sagde Herren til Josva, Nuns Søn, som havde tjent Mose, saaledes:',
        2: 'Mose, min Tjener, er død; saa gør dig nu rede, drag over denne Jordan, du og alt dette Folk, til det Land, som jeg giver Israels Børn.',
        3: 'Hvert Sted, som eders Fodsaal skal træde paa, det har jeg givet eder, som jeg sagde til Mose;',
        4: 'fra Ørken og dette Libanon og indtil den store Flod, den Flod Frat, alt Hethiternes Land, og indtil det store Hav imod Solens Nedgang, det skal være eders Landemærke.',
        5: 'Ingen Mand skal bestaa for dit Ansigt alle dine Livs Dage; ligesom jeg var med Mose, vil jeg være med dig, jeg vil ikke slippe og ikke forlade dig.',
        6: 'Vær frimodig og vær stærk; thi du skal dele Landet til Arv iblandt dette Folk, hvilket jeg tilsvor deres Fædre at ville give dem.',
        7: 'Vær kun saare frimodig og stærk, saa du tager Vare paa at gøre efter al den Lov, som Mose, min Tjener, bød dig; vig ikke fra den til højre eller venstre Side, at du kan handle klogelig paa al den Vej, som du skal vandre paa.',
        8: 'Denne Lovs Bog skal ikke vige fra din Mund, men du skal grunde paa den Dag og Nat, paa det du kan tage Vare paa at gøre efter alt det, som er skrevet i den; thi da skal det gaa dig vel i dine Veje, og da skal du handle klogelig.',
        9: 'Har jeg ikke befalet dig: Vær frimodig og stærk, forfærdes ikke og ræddes ikke; thi Herren din Gud er med dig paa al den Vej, som du skal vandre paa.',
        10: 'Da bød Josva Folkets Fogeder og sagde:',
        11: 'Gaar midt igennem Lejren og byder Folket og siger: Bereder eder Tæring; thi inden tre Dage skulle I gaa over denne Jordan for at komme til at eje Landet, som Herren eders Gud giver eder at eje.',
        12: 'Og til Rubeniterne og til Gaditerne og til Halvdelen af Manasse Stamme sagde Josva:',
        13: 'Kommer det Ord i Hu, som Mose, Herrens Tjener, bød eder og sagde: Herren eders Gud skaffer eder Rolighed og giver eder dette Land.',
        14: 'Lader eders Hustruer og eders smaa Børn og eders Kvæg blive i Landet, som Mose har givet eder paa denne Side Jordanen; men I skulle drage over bevæbnede for eders Brødres Ansigt, alle vældige til Strid, og hjælpe dem,',
        15: 'indtil Herren skaffer eders Brødre Rolighed som eder, at ogsaa de kunne eje Landet, som Herren eders Gud skal give dem; saa skulle I vende tilbage til eders Ejendoms Land og eje det, som Mose, Herrens Tjener, gav eder paa denne Side Jordanen mod Solens Opgang.',
        16: 'Og de svarede Josva og sagde: Vi ville gøre alt det, som du har budet os, og vi ville gaa til alt, hvortil du vil sende os.',
        17: 'I alle Ting, ligesom vi hørte Mose, saaledes ville vi og høre dig; vilde kun Herren din Gud være med dig, ligesom han var med Mose!',
        18: 'Hver den, som er genstridig mod din Mund og ikke hører dine Ord i alt det, du byder ham, han skal dø; vær ikkun frimodig og stærk.',
    },
    2: {
        1: 'Og Josva, Nuns Søn, sendte hemmelig to Mænd som Spejdere fra Sittim og sagde: Gaar hen, beser Landet og Jeriko; og de gik hen og kom ind i en Kvindes, en Skøges Hus, og hendes Navn var Rahab, og de laa der.',
        2: 'Da blev der sagt til Kongen af Jeriko saaledes: Se, i Nat er der komne Mænd hid af Israels Børn for at udforske Landet.',
        3: 'Da sendte Kongen af Jeriko Bud til Rahab og lod sige: Før de Mænd ud, som kom til dig, som kom til dit Hus; thi de ere komne til at udforske alt Landet.',
        4: 'Men Kvinden havde taget de to Mænd og skjult dem; og hun sagde saaledes: Mændene kom til mig, men jeg vidste ikke, hvorfra de vare.',
        5: 'Og det skete, der de vilde lukke Porten, da det var mørkt, gik Mændene ud, jeg ved ikke, hvor de Mænd gik hen; forfølger dem snart, thi saa skulle I naa dem.',
        6: 'Men hun havde ladet dem stige op paa Taget og skjult dem under Hørstilkene, som vare udbredte af hende paa Taget.',
        7: 'Og Mændene forfulgte dem paa Vejen til Jordanen indtil Færgestederne, og man lukkede Porten til, efter at de, som forfulgte dem, vare udgangne.',
        8: 'Og førend de havde lagt sig, gik hun op til dem paa Taget,',
        9: 'og hun sagde til Mændene: Jeg ved, at Herren har givet eder Landet, og at Forfærdelse for eder er falden paa os, og at Landets Indbyggere ere mistrøstige for eders Ansigt.',
        10: 'Thi vi have hørt, at Herren udtørrede Vandet i det røde Hav for eders Ansigt, der I gik ud af Ægypten, og hvad I gjorde ved Amoriternes to Konger, som vare paa hin Side Jordanen, Sihon og Og, hvilke I ødelagde.',
        11: 'Og vi have hørt det, og vort Hjerte er mistrøstigt, og intet Mod bestaar ydermere i nogen for eders Ansigt; thi Herren eders Gud, han er en Gud i Himmelen oventil og paa Jorden nedentil.',
        12: 'Og nu, kære, sværger mig ved Herren, efterdi jeg gjorde Miskundhed mod eder, at I og ville gøre Miskundhed imod min Faders Hus og give mig et sikkert Tegn,',
        13: 'at I ville lade min Fader og min Moder og mine Brødre og mine Søstre leve, og alt det, de have, og fri vore Sjæle fra Døden.',
        14: 'Og Mændene sagde til hende: Vore Sjæle skulle være i Stedet for eders til at dø, naar I kun ikke kundgør denne vor Handel; og det skal ske, naar Herren giver os Landet, da ville vi vise Miskundhed og Troskab imod dig.',
        15: 'Saa lod hun dem ned ved et Reb igennem Vinduet; thi hendes Hus var ved Stadens Mur, og hun boede ved Muren.',
        16: 'Og hun sagde til dem: Gaar op paa Bjerget, at de, som forfølge eder, ikke skulle møde eder, og skjuler eder der i tre Dage, indtil de komme igen, som forfølge eder, og siden kunne I gaa eders Vej.',
        17: 'Og Mændene sagde til hende: Vi ville være løste fra denne din Ed, som du kom os til at sværge:',
        18: 'Se, naar vi komme ind i Landet, da skal du binde denne Skarlagens Snor i Vinduet, igennem hvilket du har ladet os ned, og du skal samle til dig i Huset din Fader og din Moder og dine Brødre og din Faders ganske Hus;',
        19: 'og det skal ske, hver den, som gaar ud af dit Huses Døre udenfor, hans Blod skal være paa hans Hoved, og vi skulle være uskyldige; men hver den, som er med dig i Huset, hans Blod skal være paa vort Hoved, dersom der bliver lagt Haand paa ham.',
        20: 'Men dersom du kundgør denne vor Handel, da ville vi være løste fra den Ed, som du kom os til at sværge.',
        21: 'Og hun sagde: Det skal saa være efter eders Ord, og hun lod dem gaa, og de gik; og hun bandt den Skarlagens Snor i Vinduet.',
        22: 'Saa gik de hen og kom paa Bjerget og bleve der tre Dage, indtil de, som forfulgte dem, vendte tilbage; men Forfølgerne ledte paa hele Vejen og fandt dem ikke.',
        23: 'Saa vendte de to Mænd tilbage og gik ned ad Bjerget og for over og kom til Josva, Nuns Søn, og de fortalte ham alting, som havde rammet dem.',
        24: 'Og de sagde til Josva: Herren har givet alt Landet i vor Haand, ja ogsaa alle Landets Indbyggere ere mistrøstige for vort Ansigt.',
    },
    3: {
        1: 'Og Josva stod aarle op om Morgenen, og de rejste fra Sittim og kom til Jordanen, han og alle Israels Børn; og de bleve der om Natten, førend de droge over.',
        2: 'Og det skete, der tre Dage vare til Ende, da gik Fogederne midt igennem Lejren.',
        3: 'Og de bøde Folket og sagde: Naar I se Herrens, eders Guds Pagts Ark, og Præsterne, Leviterne, som bære den, saa skulle I rejse ud fra eders Sted og gaa efter den;',
        4: '— dog at der skal være Rum imellem eder og imellem den, ved tusinde Alen i Maal, I skulle ikke komme nær til den; — paa det at I skulle vide den Vej, paa hvilken I skulle gaa; thi I have ikke tilforn draget over paa den Vej.',
        5: 'Og Josva sagde til Folket: Helliger eder; thi Herren skal gøre underlige Ting i Morgen iblandt eder.',
        6: 'Og Josva sagde til Præsterne: Bærer Pagtens Ark og gaar over foran Folket; og de bare Pagtens Ark og gik foran Folket.',
        7: 'Og Herren sagde til Josva: Paa den Dag vil jeg begynde at gøre dig stor for al Israels Øjne, og de skulle vide, at ligesom jeg var med Mose, saa vil jeg og være med dig.',
        8: 'Men du skal byde Præsterne, som bære Pagtens Ark, og sige: Naar I komme til det yderste af Jordanens Vande, da skulle I blive staaende i Jordanen.',
        9: 'Og Josva sagde til Israels Børn: Kommer nær hid og hører Herren eders Guds Ord.',
        10: 'Og Josva sagde: Derpaa skulle I vide, at den levende Gud er midt iblandt eder og skal fordrive for eders Ansigt Kananiterne og Hethiterne og Heviterne og Feresiterne og Girgasiterne og Amoriterne og Jebusiterne.',
        11: 'Se, al Jordens Herres Pagts Ark gaar over for eders Ansigt igennem Jordanen.',
        12: 'Saa tager eder nu tolv Mænd af Israels Stammer, een Mand af hver Stamme.',
        13: 'Og det skal ske, naar Præsterne, som bære Herrens, al Jordens Herres, Ark, med Fodsaalerne staa stille i Jordanens Vande, da skal Jordanens Vande afskæres, nemlig de Vande, som komme ned ovenfra; og de skulle staa som een Dynge.',
        14: 'Og det skete, der Folket drog ud af deres Telte for at gaa over Jordanen, da bare Præsterne Pagtens Ark for Folkets Ansigt.',
        15: 'Og der de, som bare Arken, kom til Jordanen, og Præsterne, som bare Arken, vædede deres Fødder yderst i Vandet, (men Jordanen var fuld over alle sine Bredder hele Høsten igennem):',
        16: 'Da stod det Vand stille, som kom ned ovenfra, det rejste sig til een Dynge saare langt borte ved den Stad Adam, som ligger op til Zarthans Side, men det, som løb ned til Havet ved den slette Mark, nemlig Salthavet, det blev aldeles afskaaret; saa gik Folket over imod Jeriko.',
        17: 'Og Præsterne, som bare Herrens Pagts Ark, stode fast paa det tørre, midt i Jordanen; og al Israel gik over paa det tørre, indtil det ganske Folk var gaaet helt over Jordanen.',
    },
    4: {
        1: 'Og det skete, der alt Folket var gaaet helt over Jordanen, da sagde Herren til Josva:',
        2: 'Tager eder tolv Mænd af Folket, een Mand af hver Stamme,',
        3: 'og byder dem og siger: Optager eder herfra, midt af Jordanen, tolv Stene fra det Sted, som Præsternes Fødder staa fast paa, og bærer dem over med eder og lader dem blive paa det Sted, hvor I blive denne Nat over.',
        4: 'Da kaldte Josva ad de tolv Mænd, som han havde til Rede af Israels Børn, een Mand af hver Stamme;',
        5: 'og Josva sagde til dem: Gaar over frem foran Herren eders Guds Ark til midt i Jordanen, og opløfter eder hver een Sten paa sin Skulder efter Tallet paa Israels Børns Stammer,',
        6: 'at det skal være et Tegn midt iblandt eder, naar eders Børn herefter spørge og sige: Hvad betyde eder disse Stene?',
        7: 'Og I skulle sige til dem, at Jordanens Vand blev afskaaret for Herrens Pagts Ark; der den gik igennem Jordanen, da blev Jordanens Vand afskaaret; og disse Stene skulle være til en Ihukommelse for Israels Børn evindeligen.',
        8: 'Og Israels Børn gjorde saaledes, som Josva bød, og optoge tolv Stene midt af Jordanen, som Herren havde sagt til Josva, efter Tallet paa Israels Børns Stammer; og de førte dem med sig over til det Sted, hvor de bleve om Natten, og de lode dem blive der.',
        9: 'Og tolv Stene oprejste Josva midt i Jordanen, nede, hvor Præsterne, som bare Pagtens Ark, havde staaet med deres Fødder, og de ere der indtil denne Dag.',
        10: 'Og Præsterne, som bare Arken, bleve staaende midt i Jordanen, indtil hvert Ord var fuldkommet, som Herren havde talet til Folket, efter alt det, som Mose havde befalet Josva; og Folket skyndte sig og gik over.',
        11: 'Og det skete, der det ganske Folk var gaaet helt over, da kom Herrens Ark og Præsterne over, for Folkets Ansigt.',
        12: 'Og Rubens Børn og Gads Børn og Halvdelen af Manasse Stamme gik over bevæbnede, foran Israels Børns Ansigt, saaledes som Mose havde talet til dem.',
        13: 'Ved fyrretyve Tusinde, bevæbnede til Strid, gik de over for Herrens Ansigt til Krigen paa Jerikos slette Marker.',
        14: 'Paa den Dag gjorde Herren Josva stor for al Israels Øjne; og de frygtede ham, saaledes som de frygtede Mose, alle hans Livs Dage.',
        15: 'Og Herren sagde til Josva:',
        16: 'Byd Præsterne, som bære Vidnesbyrdets Ark, at de stige op af Jordanen.',
        17: 'Saa bød Josva Præsterne, og sagde: Stiger op af Jordanen!',
        18: 'Og det skete, der Præsterne, som bare Herrens Pagts Ark, stege op midt af Jordanen, saa snart Præsternes Fodsaaler havde betraadt det tørre, da kom Jordanens Vand tilbage til sit Sted og gik som tilforn over alle sine Bredder.',
        19: 'Og Folket steg op af Jordanen paa den tiende Dag i den første Maaned, og de lejrede sig i Gilgal, paa Østgrænsen af Jerikos Landemærke.',
        20: 'Og de tolv Stene, som de toge af Jordanen, oprejste Josva i Gilgal.',
        21: 'Og han sagde til Israels Børn: Naar eders Børn herefter spørge deres Fædre og sige: Hvad betyde disse Stene?',
        22: 'da skulle I kundgøre eders Børn det og sige: Israel gik paa det tørre igennem denne Jordan,',
        23: 'thi Herren eders Gud udtørrede Jordanens Vande for eders Ansigt, indtil I kom over, ligesom Herren eders Gud gjorde ved det røde Hav, hvilket han udtørrede for vort Ansigt, indtil vi kom over,',
        24: 'at alle Folk paa Jorden Skulle kende Herrens Haand, at den er stærk, at I skulle frygte Herren eders Gud alle Dage.',
    },
    5: {
        1: 'Og det skete, der alle Amoriternes Konger, som boede paa hin Side Jordanen imod Vesten, og alle Kananiternes Konger, som boede ved Havet, hørte, at Herren havde udtørret Jordanens Vande for Israels Børns Ansigt, indtil de kom over, da blev deres Hjerte mistrøstigt, og der var ikke ydermere Mod i dem for Israels Børns Ansigt.',
        2: 'Paa den Tid sagde Herren til Josva: Gør dig Stenknive og omskær Israels Børn igen anden Gang.',
        3: 'Da gjorde Josva sig Stenknive og omskar Israels Børn ved Araloths Høj.',
        4: 'Og dette er Sagen, hvorfor Josva omskar dem: Alt Folket af Mandkøn, som var udgaaet af Ægypten, alt Krigsfolket var død i Ørken paa Vejen, siden de gik ud af Ægypten.',
        5: 'Thi alt Folket, som udgik, var omskaaret; men alt Folket, som var født i Ørken paa Vejen, siden de udgik af Ægypten, havde de ikke omskaaret.',
        6: 'Thi Israels Børn vandrede fyrretyve Aar i Ørken, indtil alt det Folk, Krigsfolket, som udgik af Ægypten, var uddød, de som ikke havde hørt Herrens Røst, saa at Herren svor dem, at han ikke vilde lade dem se det Land, som Herren havde tilsvoret deres Fædre at give os, et Land, som flyder med Mælk og Honning.',
        7: 'Og han oprejste deres Børn i deres Sted; dem omskar Josva, thi de havde Forhud, eftersom man ikke havde omskaaret dem paa Vejen.',
        8: 'Og det skete, der de vare færdige med at omskære alt Folket, da bleve de paa deres Sted i Lejren, indtil de bleve karske.',
        9: 'Og Herren sagde til Josva: I Dag har jeg afvæltet Ægyptens Skændsel fra eder; og man kaldte samme Steds Navn Gilgal indtil denne Dag.',
        10: 'Og Israels Børn lejrede sig i Gilgal, og de holdt Paaske den fjortende Dag i Maaneden om Aftenen, paa Jerikos slette Marker.',
        11: 'Og de aade af Landets Grøde fra anden Paaskedag, nemlig usyrede Brød og ristede Aks, paa selvsamme Dag.',
        12: 'Saa holdt Mannaen op, anden Dag efter at de havde ædt af Landets Grøde, og Israels Børn havde ikke ydermere Manna; men de aade af Kanaans Lands nye Grøde i samme Aar.',
        13: 'Og det skete, der Josva var ved Jeriko, at han opløftede sine Øjne og saa, og se, en Mand stod lige imod ham og havde sit dragne Sværd i sin Haand; og Josva gik til ham og sagde til ham: Hører du os til eller vore Fjender?',
        14: 'Og han sagde: Nej! men jeg er en Fyrste over Herrens Hær, nu kom jeg! Da faldt Josva paa sit Ansigt til Jorden og tilbad og sagde til ham: Hvad taler min Herre til sin Tjener?',
        15: 'Og Fyrsten over Herrens Hær sagde til Josva: Drag din Sko af din Fod, thi det Sted, som du staar paa, det er helligt; og Josva gjorde saa.',
    },
    6: {
        1: 'Og Jeriko havde lukket for sig og var tillukket for Israels Børns Ansigt; der kunde ingen gaa ud, ej heller komme ind.',
        2: 'Og Herren sagde til Josva: Se, i din Haand har jeg givet Jeriko og dens Konge, som ere vældige til Strid.',
        3: 'Og I skulle gaa omkring Staden, alle Krigsmændene, saa at de gaa rundt om Staden een Gang; saaledes skal du gøre seks Dage.',
        4: 'Og syv Præster skulle bære syv fuldtonende Basuner foran Arken, og paa den syvende Dag skulle I gaa om Staden syv Gange, og Præsterne skulle blæse i Basunerne.',
        5: 'Og det skal ske, naar man blæser langsomt i Hornet, naar I høre Basunens Lyd, da skal alt Folket skrige med et stort Skrig; saa skal Stadens Mur falde lige ned, og Folket skal stige op, hver lige frem for sig.',
        6: 'Saa kaldte Josva, Nuns Søn, ad Præsterne og sagde til dem: Bærer Pagtens Ark, og lader syv Præster bære de syv fuldtonende Basuner foran Herrens Ark.',
        7: 'Og han sagde til Folket: Gaar frem og gaar omkring Staden; og hvo som er bevæbnet, gaa frem foran Herrens Ark.',
        8: 'Og det skete, der Josva havde sagt dette til Folket, da gik syv Præster frem, som bare de syv fuldtonende Basuner for Herrens Ansigt, og blæste i Basunerne; og Herrens Pagts Ark fulgte efter dem.',
        9: 'Og hver, som var bevæbnet, gik foran Præsterne, som blæste i Basunerne; og Troppen, som sluttede, gik efter Arken, medens man vedblev at blæse i Basunerne.',
        10: 'Og Josva bød Folket og sagde: I skulle ikke skrige og ej lade eders Røst høre, og der skal ikke et Ord udgaa af eders Mund, indtil den Dag jeg siger til eder: Skriger! da skulle I skrige.',
        11: 'Saa gik Herrens Ark omkring, saa at den gik rundt om Staden een Gang; og de kom i Lejren og bleve om Natten i Lejren.',
        12: 'Og Josva stod tidlig op om Morgenen, og Præsterne bare Herrens Ark.',
        13: 'Og de syv Præster, som bare de syv fuldtonende Basuner foran Herrens Ark, gik stedse og blæste i Basunerne; og hver bevæbnet gik for deres Ansigt, og Troppen, som sluttede, gik efter Herrens Ark, medens man vedblev at blæse i Basunerne.',
        14: 'Og de gik omkring Staden paa den anden Dag een Gang, og de vendte tilbage til Lejren; saaledes gjorde de seks Dage.',
        15: 'Og det skete paa den syvende Dag, da stode de tidlig op, der Morgenrøden brød frem, og de gik omkring Staden syv Gange, efter den samme Vis, kun at de den samme Dag kom syv Gange omkring Staden.',
        16: 'Og det skete den syvende Gang, da blæste Præsterne i Basunerne, og Josva sagde til Folket: Skriger! thi Herren har givet eder Staden.',
        17: 'Og Staden, den og alt det, som er i den, skal være sat i Band for Herren; kun den Skøge Rahab skal leve, hun og alle de, som ere i Huset med hende; thi hun skjulte Budene, som vi udsendte.',
        18: 'Kun maa I forvare eder for det bandlyste, at I ikke komme under Band og tage af det bandlyste og sætte Israels Lejr i Band og forstyrre den.',
        19: 'Men alt Sølv og Guld og Kobberkar og Jern, det skal være helligt for Herren; det skal komme til Herrens Liggendefæ.',
        20: 'Og Folket skreg, da de blæste i Basunerne; ja det skete, der Folket hørte Basunernes Lyd, da skreg Folket med et stort Skrig, og Muren faldt lige ned, og Folket steg op i Staden, hver lige frem for sig, og de indtoge Staden.',
        21: 'Og de ødelagde alt det, som var i Staden, baade Mand og Kvinde, baade ung og gammel, og Øksne og Faar og Asener, med skarpe Sværd.',
        22: 'Men Josva sagde til de to Mænd, som havde spejdet Landet: Gaar i den Kvindes, den Skøges Hus, og udfører Kvinden derfra og alt det, som hører hende til, som I have svoret hende.',
        23: 'Da gik de unge Karle, Spejderne, ind og udførte Rahab og hendes Fader og hendes Moder og hendes Brødre, og alt det, som hørte hende til, og al hendes Slægt udførte de; og de lode dem blive uden for Israels Lejr.',
        24: 'Men Staden opbrændte de med Ild og alt det, som var i den; alene Sølvet og Guldet og Kobberkarrene og Jernet, det gave de til Herrens Huses Liggendefæ.',
        25: 'Men Josva lod Rahab, den Skøge, og hendes Faders Hus og alt det, som hørte hende til, leve, og hun boede midt iblandt Israel indtil denne Dag; thi hun skjulte Budene, som Josva havde udsendt til at spejde Jeriko.',
        26: 'Og paa den samme Tid tog Josva en Ed af dem og sagde: Forbandet være den Mand for Herrens Ansigt, som opstaar og bygger denne Stad Jeriko; naar han lægger dens Grundvold, koste det ham hans førstefødte, og naar han sætter dens Porte, koste det ham hans yngste Søn.',
        27: 'Saa var Herren med Josva, og hans Rygte var over det ganske Land.',
    },
    7: {
        1: 'Men Israels Børn forgrebe sig saare paa det bandlyste Gods; thi Akan, en Søn af Karmi, som var en Søn af Sabdi, Seras Søn, af Judas Stamme, tog af det bandlyste, og Herrens Vrede optændtes imod Israels Børn.',
        2: 'Og Josva udsendte Mænd fra Jeriko mod Ai, som ligger ved Beth-Aven Østen for Bethel, og sagde til dem: Gaar op og bespejder Landet; og Mændene gik op og bespejdede Ai.',
        3: 'Og de kom tilbage til Josva og sagde til ham: Lad ikke alt Folket drage op, lad ved to Tusinde Mand eller ved tre Tusinde Mand drage op og slaa Ai; du skal ikke lade det ganske Folk ulejlige sig derhen; thi de ere faa.',
        4: 'Saa droge af Folket ved tre Tusinde Mænd op derhen; men de flyede for Ais Mænds Ansigt.',
        5: 'Og Mændene af Ai sloge ved seks og tredive Mænd af dem og forfulgte dem foran Porten indtil Sebarim og sloge dem, hvor Vejen gik nedad; da blev Folkets Hjerte mistrøstigt og blev som Vand.',
        6: 'Og Josva sønderrev sine Klæder og faldt paa sit Ansigt til Jorden for Herrens Ark indtil Aftenen, han og de Ældste af Israel, og de kastede Støv paa deres Hoved.',
        7: 'Og Josva sagde: Ak, Herre, Herre! hvi lod du dog dette Folk gaa over Jordanen for at give os i Amoriternes Haand til vor Fordærvelse? og gid vi havde ladet os nøje og vare blevne paa hin Side Jordanen!',
        8: 'Hør mig, Herre! hvad skal jeg sige, efter at Israel vender Ryggen for sine Fjenders Ansigt?',
        9: 'Naar Kananiterne og alle Landets Indbyggere høre det, da omringe de os og udrydde vort Navn af Jorden; og hvad vil du gøre ved dit store Navn?',
        10: 'Da sagde Herren til Josva: Staa du op; hvorfor faldt du paa dit Ansigt?',
        11: 'Israel har syndet, ja, de have overtraadt min Pagt, hvilken jeg bød dem; ja, de toge af det bandlyste Gods, ja, de stjal og dulgte det ogsaa og lagde det iblandt deres eget Tøj.',
        12: 'Og Israels Børn skulle ikke kunne staa for deres Fjenders Ansigt, de maa vende Ryggen for deres Fjenders Ansigt, thi de ere i Band; jeg skal ikke mere blive ved at være med eder, dersom I ikke fjerne denne Band fra eders Midte.',
        13: 'Staa op, hellig Folket, og sig: Helliger eder til i Morgen; thi saa siger Herren Israels Gud: Der er Band iblandt dig, Israel! du kan ikke staa for dine Fjenders Ansigt, førend I borttage den Band fra eders Midte.',
        14: 'Og i Morgen tidlig skulle I komme frem efter eders Stammer; og det skal ske, hvilken Stamme Herren rammer paa, den skal nærme sig, Slægt for Slægt, og den Slægt, som Herren rammer paa, den skal nærme sig, Hus for Hus, og det Hus, som Herren rammer paa, det skal nærme sig, Mand for Mand.',
        15: 'Og det skal ske, den, som bliver ramt som bandlyst, han skal opbrændes med Ild, han og alt det, han har, fordi han har overtraadt Herrens Pagt, og fordi han har gjort en Daarlighed i Israel.',
        16: 'Og Josva stod tidlig op om Morgenen og lod Israel nærme sig Stamme for Stamme, og Judas Stamme blev ramt.',
        17: 'Og han lod Judas Slægt nærme sig, og Seraiternes Slægt blev ramt.',
        18: 'Og han lod Seraiternes Slægt nærme sig, Mand for Mand, og Sabdi blev ramt, og han lod hans Hus nærme sig, Mand for Mand, og Akan, en Søn af Karmi, som var Sabdi Søn, Seras Søn, af Judas Stamme, blev ramt.',
        19: 'Og Josva sagde til Akan: Min Søn, giv dog Herren Israels Gud Ære og giv ham Lov, og giv mig nu til Kende, hvad du har gjort, dølg det ikke for mig!',
        20: 'Og Akan svarede Josva og sagde: Sandelig, jeg syndede for Herren Israels Gud, og saa og saa gjorde jeg.',
        21: 'Thi jeg saa en kostelig babylonisk Kappe iblandt Byttet og to Hundrede Sekel Sølv og en Guldtunge, hvis Vægt var halvtredsindstyve Sekel, og jeg fik Lyst til dem og tog dem, og se, de ere skjulte i Jorden, midt i mit Telt, og Sølvet derunder.',
        22: 'Da sendte Josva Bad hen, og de løb til Teltet; og se, det var skjult i hans Telt og Sølvet derunder.',
        23: 'Og de toge de Ting ud af Teltet og førte dem til Josva og til alle Israels Børn; og de lagde dem frem for Herrens Ansigt.',
        24: 'Saa tog Josva og al Israel med ham Akan, Seras Søn, og Sølvet og den kostelige Kappe og Guldtungen og hans Sønner og hans Døtre og hans Øksne og hans Asener og hans Faar og hans Telt, og alt det han havde, og de førte ham op i Akors Dal.',
        25: 'Og Josva sagde: Hvi har du forstyrret os? Herren skal forstyrre dig paa denne Dag; og al Israel stenede ham med Stene og opbrændte dem med Ild og kastede Stene over dem.',
        26: 'Og de opkastede en stor Stenhob over ham indtil denne Dag, og Herren vendte om fra sin strenge Vrede; derfor kaldte man det samme Steds Navn Akors Dal; den er der indtil denne Dag.',
    },
    8: {
        1: 'Og Herren sagde til Josva: Frygt ikke og ræddes ikke, tag med dig alt Krigsfolket og gør dig rede, drag op mod Ai; se, jeg har givet Kongen af Ai og hans Folk og hans Stad og hans Land i din Haand.',
        2: 'Og du skal gøre ved Ai og dens Konge, ligesom du gjorde ved Jeriko og dens Konge, kun dens Bytte og dens Kvæg skulle I røve for eder selv; sæt dig et Baghold bag ved Staden!',
        3: 'Da gjorde Josva sig rede og alt Krigsfolket at drage op til Ai, og Josva udvalgte tredive Tusinde Mand, vældige til Strid, og sendte dem hen om Natten.',
        4: 'Og han bød dem og sagde: Ser til, I som ere i Baghold ved Staden bag ved Staden, I skulle ikke holde eder saare langt fra Staden, og I skulle være alle sammen rede.',
        5: 'Men jeg og alt det Folk, som er med mig, vi ville komme nær til Staden, og det skal ske, naar de gaa ud imod os som i Begyndelsen, da ville vi fly for deres Ansigt.',
        6: 'Og de skulle gaa efter os, indtil vi faa draget dem bort fra Staden; thi de skulle tænke: De fly for vort Ansigt ligesom i Begyndelsen; og vi ville fly for deres Ansigt.',
        7: 'Da skulle I rejse eder af Bagholdet og indtage Staden; og Herren eders Gud skal give den i eders Haand.',
        8: 'Og det skal ske, naar I have indtaget Staden, da skulle I sætte Ild paa Staden; I skulle gøre efter Herrens Ord; se, jeg har befalet eder det.',
        9: 'Saa sendte Josva dem, og de gik til Bagholdet, og de bleve imellem Bethel og Ai, Vesten for Ai; men Josva overnattede den samme Nat midt iblandt Folket.',
        10: 'Og Josva stod tidlig op om Morgenen og mønstrede Folket; og han drog op, han og de Ældste af Israel, fremmest for Folket mod Ai.',
        11: 'Og alt Krigsfolket, som var hos ham, drog op og holdt sig nær til og kom lige for Staden; og de sloge Lejr Norden for Ai, saa at Dalen var imellem ham og imellem Ai.',
        12: 'Og han havde taget ved fem Tusinde Mand og sat dem i Baghold imellem Bethel og imellem Ai, Vesten for Staden.',
        13: 'Og da Folket havde opstillet hele Lejren, som var Nord for Staden, og Bagholdet, som var Vest for Staden, drog Josva samme Nat ned midt i Dalen.',
        14: 'Og det skete, der Kongen af Ai saa det, da skyndte Mændene af Staden sig og stode tidlig op og gik ud imod Israel til Striden, han og hele hans Folk, paa en bestemt Tid, foran den slette Mark; men han vidste ikke, at der var et Baghold paa ham bag ved Staden.',
        15: 'Men Josva og al Israel lode sig slaa for deres Ansigt, og de flyede ad Vejen mod Ørken.',
        16: 'Da blev alt Folket sammenraabt, som var i Staden, for at forfølge dem; og de forfulgte Josva, og de bleve dragne bort fra Staden.',
        17: 'Og der blev ikke en Mand tilovers i Ai og Bethel, som ej drog ud efter Israel; og de lode Staden aaben og forfulgte Israel.',
        18: 'Da sagde Herren til Josva: Udræk dit Kastespyd, som du har i din Haand, mod Ai, thi jeg vil give den i din Haand; og Josva udrakte Spydet, som han havde i sin Haand, mod Staden.',
        19: 'Da rejste Bagholdet sig hasteligen fra sit Sted, og de løb, der han udstrakte sin Haand, og kom i Staden og indtoge den; og de skyndte sig og satte Ild paa Staden.',
        20: 'Og Mændene af Ai vendte sig tilbage, og de saa, og se, Røgen af Staden steg op mod Himmelen, og der var ingen Udvej for dem at fly hid eller did; og det Folk, som flyede til Ørken, vendte sig imod dem, som forfulgte dem.',
        21: 'Da Josva og al Israel saa, at Bagholdet havde indtaget Staden, og at Røgen steg op af Staden, da vendte de tilbage og sloge Mændene af Ai.',
        22: 'Og hine gik ud af Staden mod dem, saa de vare midt imellem Israel, hine vare paa den ene Side, og disse paa den anden Side; og de sloge dem, indtil ingen blev tilovers af dem som undkommen eller undsluppen.',
        23: 'Og de grebe Kongen af Ai levende, og de førte ham frem til Josva.',
        24: 'Og det skete, der Israel var kommet til Ende med at slaa alle Ais Indbyggere ihjel paa Marken i Ørken, hvor de forfulgte dem, og de vare faldne alle sammen for skarpe Sværd, indtil det var forbi med dem: Da vendte al Israel tilbage til Ai og slog den med skarpe Sværd.',
        25: 'Og alle de, som faldt paa samme Dag, baade Mænd og Kvinder, vare tolv Tusinde, alle Folk af Ai.',
        26: 'Og Josva tog ikke sin Haand, som han havde udrakt med Spydet, tilbage, førend han havde ødelagt alle Ais Indbyggere.',
        27: 'Ikkun Kvæget og Byttet og Rovet af samme Stad røvede Israel for sig selv efter Herrens Ord, som han bød Josva.',
        28: 'Og Josva afbrændte Ai, og han gjorde af den en stedsevarende Dynge, en øde Plads, indtil denne Dag.',
        29: 'Og han lod Kongen af Ai ophænge paa et Træ indtil Aftens Tid; og der Solen gik ned, bød Josva, at de skulde nedtage hans døde Krop af Træet, og de kastede den for Indgangen til Stadens Port, og de opkastede en stor Stenhob over ham, som er der indtil denne Dag.',
        30: 'Da byggede Josva Herren, Israels Gud, et Alter paa Ebals Bjerg,',
        31: 'ligesom Mose, Herrens Tjener, bød Israels Børn efter det, som er skrevet i Mose Lovbog: Et Alter af hele Stene, over hvilket der ikke er ført noget Jern; og de ofrede derpaa Brændofre for Herren, og de slagtede Takofre.',
        32: 'Og han skrev der paa Stenene en Afskrift af Mose Lov, som han havde skrevet for Israels Børns Ansigt.',
        33: 'Og al Israel og dets Ældste og Fogeder og Dommere stode paa begge Sider af Arken tværs over for Præsterne, Leviterne, som bare Herrens Pagts Ark, saa vel den fremmede som den indfødte, Halvdelen deraf hen imod Garizims Bjerg, og Halvdelen deraf hen imod Ebals Bjerg, saaledes som Mose, Herrens Tjener, fra først af havde budet at velsigne Israels Folk.',
        34: 'Og derefter oplæste han alle Lovens Ord, Velsignelsen og Forbandelsen, efter alt det, som er skrevet i Lovbogen.',
        35: 'Der var ikke et Ord af alt det, som Mose havde budet, hvilket Josva ej lod oplæse for al Israels Forsamling, endog for Kvinderne og smaa Børn og den fremmede, som vandrede midt iblandt dem.',
    },
    9: {
        1: 'Og det skete, der alle Kongerne, som vare paa denne Side Jordanen, i Bjerglandet og i Lavlandet og paa hele Kysten af det store Hav tværs overfor Libanon, samt Hethiterne og Amoriterne, Kananiterne og Feresiterne, Heviterne og Jebusiterne, hørte det:',
        2: 'Da samlede de sig til Hobe at stride imod Josva og imod Israel endrægteligen.',
        3: 'Da Indbyggerne af Gibeon havde hørt, hvad Josva havde gjort ved Jeriko og Ai,',
        4: 'da handlede ogsaa de med List og gik hen og gave sig ud for Sendebud; og de toge gamle Sække paa deres Asener og gamle sønderrevne og bødede Læderflasker til Vin',
        5: 'og gamle og lappede Sko paa deres Fødder og gamle Klæder paa sig, og alt Brødet til deres Tæring var tørt og mullent.',
        6: 'Og de gik til Josva i Lejren ved Gilgal, og de sagde til ham og til Israels Mænd: Vi ere komne fra et langt fra liggende Land, saa gører nu Pagt med os.',
        7: 'Da sagde Israels Mænd til Heviten: Maaske du bor midt iblandt os, hvorledes kunne vi da gøre Pagt med dig.',
        8: 'Og de sagde til Josva: Vi ere dine Tjenere; og Josva sagde til dem: Hvo ere I, og hvorfra komme I?',
        9: 'Og de sagde til ham: Dine Tjenere ere komne fra et saa re langt fra liggende Land for Herren din Guds Navns Skyld; thi vi have hørt hans Rygte og alt det, som han gjorde i Ægypten.',
        10: 'Og alt det, som han gjorde ved Amoriternes to Konger, som vare paa hin Side Jordanen, ved Sihon, Kongen i Hesbon, og ved Og, Kongen i Basan, som var i Astharoth.',
        11: 'Derfor sagde vore Ældste og alle vort Lands Indbyggere til os saalunde: Tager Tæring med eder paa Vejen og gaar dem i Møde, og siger til dem: Vi ere eders Tjenere, saa gører nu Pagt med os.',
        12: 'Dette er vort Brød, det toge vi varmt med os paa Rejsen fra vore Huse den Dag, vi gik ud for at vandre til eder; men se, nu er det tørt, og det er mullent.',
        13: 'Og disse ere Læderflasker til Vin, som vi fyldte, der de vare nye, se, de ere og sønderrevne; og disse vore Klæder og vore Sko ere blevne gamle for denne saare lange Vejs Skyld.',
        14: 'Saa toge Mændene af deres Rejsekost, og de spurgte ikke Herrens Mund ad.',
        15: 'Og Josva gjorde Fred med dem og gjorde Pagt med dem, at han vilde lade dem leve; og Menighedens Fyrster tilsvore dem det.',
        16: 'Men det skete, der tre Dage vare til Ende, efter at de havde gjort Pagt med dem, da hørte de, at de vare nær hos dem, og at de boede midt iblandt dem.',
        17: 'Thi der Israels Børn rejste frem, da kom de paa den tredje Dag til deres Stæder; og deres Stæder vare Gibeon og Kefira og Beeroth og Kirjath-Jearim.',
        18: 'Og Israels Børn ihjelsloge dem ikke; thi Menighedens Fyrster havde tilsvoret dem ved Herren, Israels Gud, og al Menigheden knurrede mod Fyrsterne.',
        19: 'Da sagde alle Fyrsterne til hele Menigheden: Vi have tilsvoret dem ved Herren, Israels Gud; derfor kunne vi nu ikke røre dem.',
        20: 'Dette ville vi gøre dem: Vi ville lade dem leve, at der ikke skal komme en Vrede over os for den Eds Skyld, som vi have tilsvoret dem.',
        21: 'Fremdeles sagde Fyrsterne til dem: Lader dem leve, at de maa være Vedhuggere og Vanddragere for hele Menigheden, ligesom Fyrsterne have sagt til dem.',
        22: 'Da kaldte Josva ad dem og talede til dem og sagde: Hvi bedroge I os og sagde: Vi bo saare langt fra eder, og I bo dog midt iblandt os?',
        23: 'Derfor skulle I nu være forbandede, saa at der ikke skal være nogen iblandt eder, som jo er Træl, Vedhugger eller Vanddrager til min Guds Hus.',
        24: 'Og de svarede Josva og sagde: Fordi det blev dine Tjenere sikkert tilkendegivet, hvad Herren din Gud bød Mose sin Tjener, at han vilde give eder alt Landet og ødelægge alle Landets Indbyggere for eders Ansigt, saa frygtede vi saare for vort Liv for eders Ansigt og have gjort denne Gerning.',
        25: 'Men nu, se, vi ere i din Haand; som det er godt og som det er ret for dine Øjne at gøre os, det gør!',
        26: 'Og han gjorde saaledes mod dem; og han reddede dem fra Israels Børns Haand, og de sloge dem ikke ihjel.',
        27: 'Og Josva satte dem paa den samme Dag til Vedhuggere og Vanddragere for Menigheden og for Herrens Alter indtil denne Dag, ved det Sted, som han vilde udvælge.',
    },
    10: {
        1: 'Og det skete, der Adoni-Zedek, Kongen af Jerusalem, hørte, at Josva havde indtaget Ai og ødelagt den og gjort saa mod Ai og dens Konge, som han gjorde mod Jeriko og dens Konge, og at Indbyggerne af Gibeon havde gjort Fred med Israel og vare midt iblandt dem:',
        2: 'Da flygtede de saare, fordi Gibeon var en stor Stad som en af de kongelige Stæder, og fordi den var større end Ai, og alle Mændene derudi vare vældige Mænd.',
        3: 'Og Adoni-Zedek, Kongen af Jerusalem, sendte Bud til Hoham, Kongen af Hebron, og til Piream, Kongen af Jarmuth, og til Jafia, Kongen af Lakis, og til Debir, Kongen af Eglon, og lod sige:',
        4: 'Kommer op til mig og hjælper mig, at vi kunne slaa Gibeon; thi den har gjort Fred med Josva og med Israels Børn.',
        5: 'Og de fem amoritiske Konger samlede sig og droge op, Kongen af Jerusalem, Kongen af Hebron, Kongen af Jarmuth, Kongen af Lakis, Kongen af Eglon, de og alle deres Lejre; og de lejrede sig mod Gibeon og strede mod den.',
        6: 'Og de Mænd af Gibeon sendte til Josva til Lejren, til Gilgal, og lode sige: Drag ikke din Haand fra dine Tjenere, kom snart op til os og frels os og hjælp os; thi alle Amoriternes Konger, som bo paa Bjergene, have forsamlet sig imod os.',
        7: 'Og Josva drog op fra Gilgal, han og alt Krigsfolket med ham, og alle, som vare vældige til Strid.',
        8: 'Og Herren sagde til Josva: Frygt ikke for dem, thi jeg har givet dem i din Haand; der skal ikke en Mand af dem kunne staa for dit Ansigt.',
        9: 'Saa kom Josva hasteligen over dem; thi han drog den hele Nat op fra Gilgal.',
        10: 'Og Herren forskrækkede dem for Israels Ansigt, saa han slog dem med et svart Slag ved Gibeon; og han forfulgte dem paa Vejen, hvor man gaar op til Beth-Horon, og slog dem indtil Aseka og indtil Makkeda.',
        11: 'Og det skete, der de flyede for Israels Ansigt, og de vare der, hvor man gaar ned til Beth-Horon, da lod Herren falde store Stene af Himmelen paa dem indtil Aseka, at de døde; de vare flere, som døde af samme Hagelstene, end de, som Israels Børn sloge ihjel med Sværdet.',
        12: 'Da talede Josva til Herren paa samme Dag, der Harren gav Amoriterne for Israels Børns Ansigt, og han sagde for Israels Øjne: Sol, staa stille i Gibeon, og Maane, i Ajalons Dal!',
        13: 'Saa stod Solen stille, og Maanen blev staaende, indtil Folket havde hævnet sig paa sine Fjender; er det ikke skrevet i den oprigtiges Bog? Saa blev Solen staaende midt paa Himmelen og ilede ikke til at gaa ned henved en hel Dag.',
        14: 'Og der var ingen Dag som denne, hverken før eller efter den, at Herren hørte en Mands Røst; thi Herren stred for Israel.',
        15: 'Og Josva vendte tilbage og al Israel med ham til Lejren ved Gilgal.',
        16: 'Men hine fem Konger vare flygtede, at de havde skjult sig i den Hule ved Makkeda.',
        17: 'Og det blev Josva tilkendegivet, at man sagde: De fem Konger ere fundne skjulte i den Hule ved Makkeda.',
        18: 'Og Josva sagde: Vælter store Stene for Gabet paa Hulen, og sætter Mænd ved den for at tage Vare paa dem.',
        19: 'Og I, staar ikke stille, forfølger eders Fjender og slaar deres Bagtrop; lader dem ikke komme til deres Stæder, thi Herren eders Gud har givet dem i eders Haand.',
        20: 'Og det skete, der Josva og Israels Børn var færdige med at slaa dem med et saare stort Slag, indtil de havde gjort Ende paa dem, da vare nogle blevne tilovers af dem, og de kom ind i de faste Stæder.',
        21: 'Men alt Folket vendte tilbage til Josva til Lejren ved Makkeda med Fred; der havde ingen rørt sin Tunge imod Israels Børn, ja ikke mod nogen af dem.',
        22: 'Og Josva sagde: Aabner Gabet paa Hulen, og fører disse fem Konger ud til mig af Hulen!',
        23: 'Og de gjorde saa og førte de fem Konger ud til ham af Hulen: Kongen af Jerusalem, Kongen af Hebron, Kongen af Jarmuth, Kongen af Lakis, Kongen af Eglon.',
        24: 'Og det skete, der de havde ført disse Konger ud til Josva, da kaldte Josva ad alle Israels Mænd, og sagde til de Øverste for Krigsmændene, som droge med ham: Kommer frem, sætter eders Fødder paa disse Kongers Halse; saa kom de frem og satte deres Fødder paa deres Halse.',
        25: 'Da sagde Josva til dem: Frygter ikke og forfærdes ikke, værer frimodige og værer stærke; thi Herren skal gøre saaledes imod alle eders Fjender, dem som I stride imod.',
        26: 'Og derefter slog Josva dem og dræbte dem og hængte dem paa fem Træer, og de bleve hængende paa Træerne indtil Aftenen.',
        27: 'Og det skete ved den Tid, da Solen gik ned, bød Josva, og de toge dem ned af Træerne og kastede dem i den Hule, som de havde været skjulte i; og de lagde store Stene for Gabet af Hulen, hvor de ere indtil denne Dag.',
        28: 'Og Josva indtog Makkeda paa den samme Dag og slog den med skarpe Sværd, og dens Konge ødelagde han tillige med alle Personer, som vare i den, han lod ingen blive tilovers til at undkomme; og han gjorde mod Kongen af Makkeda, ligesom han gjorde mod Kongen af Jeriko.',
        29: 'Og Josva og hele Israel med ham gik over fra Makkeda til Libna, og han stred mod Libna.',
        30: 'Og Herren gav ogsaa den og dens Konge i Israels Haand, og han slog den med skarpe Sværd og alle Personer, som vare derudi, han lod ingen blive tilovers til at undkomme; og han gjorde mod dens Konge, ligesom han gjorde mod Kongen af Jeriko.',
        31: 'Og Josva og hele Israel med ham gik over fra Libna til Lakis; og han slog Lejr imod den og stred imod den.',
        32: 'Og Herren gav Lakis i Israels Haand, og han indtog den paa den anden Dag, og han slog den med skarpe Sværd og alle Personer, som vare i den; i alle Maader, som han gjorde mod Libna.',
        33: 'Da drog Horam, Kongen af Geser, op at hjælpe Lakis; men Josva slog ham og hans Folk, indtil han ikke lod nogen blive tilovers til at undkomme.',
        34: 'Og Josva og al Israel med ham gik over fra Lakis til Eglon; og de sloge Lejr imod den og strede imod den.',
        35: 'Og de indtoge den paa den samme Dag og sloge den med skarpe Sværd, og han ødelagde alle Personer, som vare derudi, paa den samme Dag; i alle Maader, som han gjorde mod Lakis.',
        36: 'Siden drog Josva og al Israel med ham op fra Eglon til Hebron, og de strede imod den.',
        37: 'Og de indtoge den og sloge den med skarpe Sværd og dens Konge og alle dens Stæder og alle Personer, som vare deri, han lod ingen blive tilovers til at undkomme, i alle Maader som han gjorde mod Eglon; og han ødelagde den og alle Personer, som vare i den.',
        38: 'Saa vendte Josva tilbage og hele Israel med ham til Debir og stred imod den.',
        39: 'Og han indtog den og dens Konge og alle dens Stæder, og de sloge dem med skarpe Sværd, og de ødelagde alle Personer, som vare i den, han lod ingen blive tilovers til at undkomme; ligesom han gjorde ved Hebron, saa gjorde han ved Debir og dens Konge, og ligesom han gjorde ved Libna og dens Konge.',
        40: 'Saa slog Josva alt Landet paa Bjergene og mod Sønden og Lavlandet og Dalene og alle deres Konger, han lod ingen blive tilovers til at undkomme; og han ødelagde alt det, som havde Aande, som Herren Israels Gud havde befalet.',
        41: 'Og Josva slog dem fra Kades-Barnea og indtil Gaza og alt Gosen Land og indtil Gibeon.',
        42: 'Og Josva tog alle disse Konger med deres Land paa een Gang; thi Herren Israels Gud stred for Israel.',
        43: 'Saa vendte Josva tilbage og al Israel med ham til Lejren ved Gilgal.',
    },
    11: {
        1: 'Og det skete, der Jabin, Kongen af Hazor, hørte det, da sendte han til Jobab, Kongen af Madon, og til Kongen af Simron og til Kongen af Aksaf,',
        2: 'og til de Konger, som vare mod Norden paa Bjergene og paa den slette Mark, Sønden for Kinneroths Hav og i Lavlandet og paa Højderne ved Dor ud mod Havet,',
        3: 'til Kananiterne mod Østen og mod Vesten og Amoriterne og Hethiterne og Feresiterne og Jebusiterne paa Bjergene og Heviterne neden for Hermon i Mizpa Land.',
        4: 'Og de droge ud, de og alle deres Lejre med dem, mangfoldigt Folk som Sand, der er paa Havbredden, i Mangfoldighed, og saare mange Heste og Vogne.',
        5: 'Og alle disse Konger samledes, og de kom, og de lejrede sig tilsammen ved Søen Merom, at stride imod Israel.',
        6: 'Og Herren sagde til Josva: Frygt ikke for deres Ansigt, thi i Morgen ved denne Tid vil jeg give dem alle sammen ihjelslagne for Israels Ansigt; du skal ødelægge deres Heste og opbrænde deres Vogne med Ild.',
        7: 'Og Josva og alt Krigsfolket med ham kom over dem hasteligen ved Søen Merom, og de overfaldt dem.',
        8: 'Og Herren gav dem i Israels Haand, og de sloge dem og forfulgte dem indtil det store Zidon og indtil de hede Kilder og indtil Mizpas Dal mod Østen; og de sloge dem, indtil han ikke lod dem een blive tilovers til at undkomme.',
        9: 'Da gjorde Josva ved dem, saaledes som Herren havde sagt til ham; han ødelagde deres Heste og opbrændte deres Vogne med Ild.',
        10: 'Og Josva vendte tilbage paa den samme Tid og indtog Hazor og slog dens Konge ihjel med Sværd; thi Hazor, den var tilforn Hovedstaden for alle disse Kongeriger.',
        11: 'Og de sloge alle Personer, som vare i den, med skarpe Sværd, saa de ødelagde den; der blev intet tilovers, som havde Aande; og han opbrændte Hazor med Ild.',
        12: 'Og Josva tog alle disse Kongers Stæder med alle deres Konger, og han slog dem med skarpe Sværd, saa at han ødelagde dem, saaledes som Mose, Herrens Tjener, havde befalet.',
        13: 'Dog opbrændte Israel slet ingen Stæder, som staa paa deres Høje; ikkun Hazor alene opbrændte Josva.',
        14: 'Og alt Byttet af disse Stæder og Kvæget røvede Israels Børn for sig; kun Menneskene sloge de med skarpe Sværd, indtil de havde ødelagt dem, de lode intet blive tilovers, som havde Aande.',
        15: 'Lige som Herren bød Mose sin Tjener, saa bød Mose Josva, og saa gjorde Josva, han undlod ikke noget af alt det, som Herren havde befalet Mose.',
        16: 'Og Josva indtog hele dette Land, Bjerglandet og Sydlandet og hele Gosen Land og Lavlandet og den slette Mark og Israels Bjerge med Lavlandet dertil,',
        17: 'fra det slette Bjerg, som strækker sig op mod Sejr, og indtil Baal-Gad ved Libanons Dal neden for det Bjerg Hermon; og han tog alle deres Konger og slog dem og dræbte dem.',
        18: 'Josva førte mange Aar Krig imod alle disse Konger.',
        19: 'Der var ikke en Stad, som gjorde Fred med Israels Børn, uden Heviterne, som boede i Gibeon; de indtoge alt med Krig.',
        20: 'Thi det skete af Herren, at de forhærdede deres Hjerte, saa de mødte Israel med Krig, for at han skulde ødelægge dem, saa at der ikke skulde bevises dem Naade, men at han skulde udrydde dem, som Herren bød Mose.',
        21: 'Og Josva kom paa den samme Tid og udryddede Anakiterne af Bjerget, af Hebron, af Debir, af Anab og af alle Judas Bjerge og af alle Israels Bjerge; Josva ødelagde dem med deres Stæder.',
        22: 'Der blev ingen tilovers af Anakiterne i Israels Børns Land, ikkun i Gaza, i Gath og Asdod bleve de tilovers.',
        23: 'Og Josva indtog hele Landet efter alt det, som Herren havde talet til Mose, og Josva gav Israel det til Arv efter deres Afdelinger i deres Stammer; og Landet hvilede fra Krig.',
    },
    12: {
        1: 'Og disse ere Landets Konger, som Israels Børn sloge, og hvis Land de toge i Eje paa hin Side Jordan mod Solens Opgang, fra Bækken Arnon indtil det Bjerg Hermon og al den slette Mark mod Østen:',
        2: 'Sihon, Amoriternes Konge, som boede i Hesbon, som herskede fra Aroer, som ligger ved Bredden af Arnons Bæk, og fra Midten af Dalen og over Halvdelen af Gilead og indtil Bækken Jabok, som er Ammons Børns Landemærke,',
        3: 'og over den slette Mark indtil Kinneroths Hav mod Østen og indtil Havet ved den slette Mark, Salthavet mod Østen, paa den Vej til Beth-Jesimoth, og mod Sønden nede ved Foden af Pisga',
        4: 'og Ogs Landemærke; han var Konge i Basan og en af de overblevne Kæmper, og han boede i Astharoth og i Edrei',
        5: 'og herskede over Hermons Bjerg og over Salka og over al Basan indtil Gesuriternes og Maakathiternes Landemærke og over Halvdelen af Gilead til Sihons, Hesbons Konges Landemærke.',
        6: 'Mose, Herrens Tjener, og Israels Børn sloge dem, og Mose, Herrens Tjener, gav Rubeniterne og Gaditerne og Halvdelen af Manasse Stamme det til Ejendom.',
        7: 'Og disse ere Landets Konger, som Josva og Israels Børn sloge paa denne Side Jordanen mod Vesten, fra Baal-Gad i Libanons Dal og indtil det slette Bjerg, som strækker sig op imod Sejr. Og Josva gav Israels Stammer det til Ejendom efter deres Afdelinger,',
        8: 'paa Bjergene og i Lavlandet og paa den slette Mark og i Dalene og i Ørken og mod Sønden: Hethiterne, Amoriterne og Kananiterne, Feresiterne, Heviterne og Jebusiterne.',
        9: 'Kongen af Jeriko er een; Kongen af Ai, som ligger ved Siden af Bethel, een;',
        10: 'Kongen af Jerusalem een; Kongen af Hebron een;',
        11: 'Kongen af Jarmuth een; Kongen af Lakis een;',
        12: 'Kongen af Eglon een; Kongen af Geser een;',
        13: 'Kongen af Debir een; Kongen af Geder een;',
        14: 'Kongen af Horma een; Kongen af Arad een;',
        15: 'Kongen af Libna een; Kongen af Adullam een;',
        16: 'Kongen af Makkeda een; Kongen af Bethel een;',
        17: 'Kongen af Thappua een; Kongen af Hefer een;',
        18: 'Kongen af Afek een; Kongen af Lassaron een;',
        19: 'Kongen af Madon een; Kongen af Hazor een;',
        20: 'Kongen af Simron-Meron een; Kongen af Aksaf een;',
        21: 'Kongen af Thaanak een; Kongen af Megiddo een;',
        22: 'Kongen af Kedes een; Kongen af Jokneam ved Karmel een;',
        23: 'Kongen af Dor paa Højderne af Dor een; Kongen over Gojim ved Gilgal een;',
        24: 'Kongen af Thirza een; alle Konger vare een og tredive.',
    },
    13: {
        1: 'Og Josva var gammel, han var kommen til Aars, og Herren sagde til ham: Du er gammel, du er kommen til Aars, og der er saare meget af Landet blevet tilovers at indtage.',
        2: 'Dette er Landet, som er blevet tilovers: Alle Filisternes Landskaber og alle Gesuriter:',
        3: 'Fra Sihon, som flyder foran Ægypten og indtil Ekrons Landemærke mod Norden, som regnes til Kananiterne; de fem Filisters Fyrster: Den Gaziter og den Asdoditer, den Askloniter, den Gathiter og den Ekroniter, og Aviterne;',
        4: 'mod Sønden alt Kananiternes Land og Meara, som hører Zidonierne til, indtil Afek, indtil Amoriternes Landemærke;',
        5: 'og Gibliternes Land og det hele Libanon mod Solens Opgang fra Baal-Gad neden for Hermons Bjerg, indtil man kommer til Hamath;',
        6: 'alle de, som bo paa Bjergene, fra Libanon indtil de hede Kilder, alle Zidonier; jeg vil fordrive dem fra Israels Børns Ansigt; lad det ikkun falde Israel til Arv, som jeg befalede dig.',
        7: 'Saa del nu dette Land til Arv iblandt de ni Stammer og den halve Del af Manasse Stamme;',
        8: 'med hvem Rubeniterne og Gaditerne have taget deres Arv, som Mose gav dem paa hin Side Jordanen mod Østen, ligesom Mose, Herrens Tjener, gav dem den,',
        9: 'fra Aroer, som ligger ved Bredden af Arnons Bæk, og fra den Stad, som er midt i Dalen, og alt det jævne Land ved Medba indtil Dibon,',
        10: 'og alle Stæder, som tilhørte Sihon, Amoriternes Konge, som regerede i Hesbon, indtil Ammons Børns Landemærke;',
        11: 'og Gilead og Gesuriternes og Maakathiternes Landemærke og hele Hermons Bjerg og al Basan indtil Salka,',
        12: 'hele Ogs Rige i Basan, han som regerede i Astharoth og i Edrei og var een af de overblevne Kæmper. Og Mose slog dem og fordrev dem;',
        13: 'men Israels Børn fordreve ikke Gesuriterne og Maakathiterne; men Gesur og Maakath boede iblandt Israel indtil denne Dag.',
        14: 'Alene Levi Stamme gav han ikke Arv; Herrens, Israels Guds Ildofre, de ere hans Arv, som han havde sagt til dem.',
        15: 'Men Mose havde givet Rubens Børns Stamme Arv efter deres Slægter;',
        16: 'og deres Landemærke var fra Aroer, som ligger ved Bredden af Arnons Bæk, og fra den Stad, som er midt i Dalen, og alt det jævne Land ved Medba,',
        17: 'Hesbon og alle dens Stæder, som ligger paa det jævne Land, Dibon og Bamoth-Baal og Beth-Baal-Meon',
        18: 'og Jahza og Kedemoth og Mefaath',
        19: 'og Kirjathaim og Sibma og Zereth-Sahar paa Dalens Bjerg',
        20: 'og Beth-Peor og Asdoth-Pisga og Beth-Jesimoth',
        21: 'og alle Stæderne paa det jævne Land og hele Sihons, den amoritiske Konges Rige, han, som regerede i Hesbon, hvilken Mose slog, tillige med Fyrsterne af Midian, nemlig Evi og Rekem og Zur og Hur og Reba, Sihons ypperste Mænd, som boede i Landet.',
        22: 'Og Bileam, Beors Søn, Spaamanden, slog Israels Børn ihjel med Sværd, tillige med de andre ihjelslagne.',
        23: 'Og Rubens Børns Landemærke vare Jordanen og Landemærket derhos; denne er Rubens Børns Arv efter deres Slægter, Stæderne og deres Landsbyer.',
        24: 'Og Mose havde givet Gads Stamme, Gads Børn, Arv efter deres Slægter.',
        25: 'Og Jaeser og alle Stæderne i Gilead vare deres Landemærke og Halvdelen af Ammons Børns Land, indtil Aroer, som ligger lige over for Rabbah,',
        26: 'og fra Hesbon indtil Ramath-Mizpe og Bethonim og fra Mahanaim indtil Debirs Landemærke;',
        27: 'og i Dalen: Beth-Haram og Beth-Nimra og Sukoth og Zafon, som var bleven tilovers af Sihons, Hesbons Konges, Rige, Jordanen og Landemærket derhos, indtil Enden af Kinnereths Hav, paa hin Side Jordanen mod Østen.',
        28: 'Denne er Gads Børns Arv efter deres Slægter, Stæderne og deres Landsbyer.',
        29: 'Og Mose havde givet den halve Manasse Stamme Arv, og den hørte den halve Manasse Børns Stamme til efter deres Slægter.',
        30: 'Og deres Landemærke var fra Mahanaim, hele Basan, hele Ogs, Kongen af Basans Rige, og alle Jairs Byer, som ligge i Basan, tresindstyve Stæder.',
        31: 'Og Halvdelen af Gilead og Astaroth og Edrei, Ogs Riges Stæder i Basan, gav han Makirs, Manasse Søns, Børn, Halvdelen nemlig af Makirs Børn efter deres Slægter.',
        32: 'Dette er det, som Mose uddelte til Arv paa Moabs slette Marker, paa hin Side Jordanen ved Jeriko mod Østen.',
        33: 'Men Levi Stamme havde Mose ikke givet Arv; Herren, Israels Gud, han er deres Arv, som han havde tilsagt dem.',
    },
    14: {
        1: 'Og dette er det, som Israels Børn arvede i Kanaans Land, som Eleasar, Præsten, og Josva, Nuns Søn, og Øversterne for Fædrenehusene iblandt Israels Børns Stammer, uddelte dem til Arv,',
        2: 'ved Lodkastning om deres Arv, som Herren havde befalet ved Mose, at give de ni Stammer og den halve Stamme.',
        3: 'Thi Mose havde givet de to Stammer og den halve Stamme Arv paa hin Side Jordanen; men han gav ikke Leviterne Arv midt iblandt dem.',
        4: 'Thi Josefs Børn vare to Stammer, Manasse og Efraim; men de gave ikke Leviterne nogen Del i Landet, uden Stæder at bo udi og Markerne deromkring for deres Kvæg og for deres Gods.',
        5: 'Som Herren bød Mose, saa gjorde Israels Børn, og de delte Landet.',
        6: 'Og Judas Børn gik frem til Josva i Gilgal, og Kaleb, Jefunne den Kenisiters Søn, sagde til ham: Du ved det Ord, som Herren talede til Mose, den Guds Mand, angaaende mig og dig i Kades-Barnea.',
        7: 'Jeg var fyrretyve Aar gammel, der Mose, Herrens Tjener, sendte mig fra Kades-Barnea til at spejde Landet; og jeg bragte ham Svar igen, ligesom jeg mente.',
        8: 'Men mine Brødre, som gik op med mig, mistrøstede Folkets Hjerte; men jeg efterfulgte Herren min Gud fuldkommeligen.',
        9: 'Da svor Mose paa den samme Dag og sagde: Det Land, som din Fod traadte paa, skal blive dig og dine Børn til Arv evindeligen, fordi du fuldkommeligen efterfulgte Herren min Gud.',
        10: 'Og nu, se, Herren har ladet mig leve, som han sagde, disse fyrretyve og fem Aar, fra den Tid, da Herren talede dette Ord til Mose, den Gang Israel vandrede i Ørken; og nu, se, jeg er i Dag fem og firsindstyve Aar gammel.',
        11: 'Jeg er endnu i Dag saa stærk, som paa den Dag, der Mose sendte mig: Som min Kraft var da, saa er og min Kraft nu til Krigen og til at gaa ud og til at gaa ind.',
        12: 'Saa giv mig nu dette Bjerg, som Herren talede om paa den samme Dag; thi du hørte paa den samme Dag, at Anakiterne ere der, og store og faste Stæder; maaske Herren vil være med mig, at jeg kan fordrive dem, ligesom Herren har sagt.',
        13: 'Saa velsignede Josva ham, og han gav Kaleb, Jefunne Søn, Hebron til Arv.',
        14: 'Derfor blev Hebron Kaleb, Jefunne den Kenisiters Søn, til Arv indtil denne Dag, fordi han fuldkommeligen efterfulgte Herren Israels Gud.',
        15: 'Men Hebron kaldtes tilforn Arbas Stad, han var det største Menneske iblandt Anakiterne; og Landet hvilede fra Krig.',
    },
    15: {
        1: 'Og Judas Børns Stammes Lod efter deres Slægter gik indtil Edoms Landemærke, til Ørken Zin mod Sønden, yderst Sønder paa.',
        2: 'Og deres Landemærke i Sønden var fra Salthavets Ende, fra den Odde, som vender imod Sønden.',
        3: 'Og det gaar ud Sønden om Opgangen til Akrabbim og gaar igennem til Zin og gaar op Sønden for Kades-Barnea og gaar igennem Hezron og gaar op til Addar og gaar omkring til Karkaa.',
        4: 'Og det gaar igennem til Azmon og gaar ud til Ægyptens Bæk, og Landemærkets Udgang er til Havet; dette skal være eder Landemærket Sønder paa.',
        5: 'Og Landemærket Øster paa er Salthavet indtil Jordanens Udløb; og Landemærket mod den nordre Side er fra samme Havs Odde, fra Udløbet af Jordanen.',
        6: 'Og Landemærket gaar op til Beth-Hogla og gaar igennem Norden om Beth-Araba, og Landemærket gaar saa op til Bohans, Rubens Søns, Sten.',
        7: 'Og Landemærket gaar op til Debir fra Akors Dal og vender sig mod Nord til Gilgal, som ligger tværs overfor Opgangen til Adummim, som er Sønden for Bækken, og Landemærket gaar igennem til det Vand ved En-Semes, og Udgangen derpaa er En-Rogel.',
        8: 'Og Landemærket gaar saa op til Hinnoms Søns Dal, mod den søndre Side af Jebus, det er Jerusalem; og Landemærket gaar op til Toppen af Bjerget, som ligger tværs over for Hinnoms Dal mod Vesten, og som er ved Enden af Refaims Dal mod Norden.',
        9: 'Og Landemærket bøjer sig fra Bjergets Top til Nefthoa Vandkilde og gaar ud til Stæderne paa Efrons Bjerg, og Landemærket bøjer sig til Baala, det er Kirjath-Jearim.',
        10: 'Og Landemærket gaar fra Baala mod Vesten omkring til det Bjerg Sejr og gaar igennem til den nordre Side af Har-Jearim, det er Kesalon, og det kommer ned til Beth-Semes og gaar igennem Thimna.',
        11: 'Og Landemærket gaar ud ved Nordsiden af Ekron, og Landemærket bøjer sig til Sikron og gaar over til Baala Bjerg og gaar ud ved Jabneel, og Landemærkets Udgang er mod Havet.',
        12: 'Og Landemærket Vester paa er det store Hav og Landemærket derhos; dette er Judas Børns Landemærke trindt omkring efter deres Slægter.',
        13: 'Og Kaleb, Jefunne Søn, gav man Del midt iblandt Judas Børn efter Herrens Ord til Josva, nemlig Arbas, Anaks Faders, Stad, det er Hebron.',
        14: 'Og Kaleb fordrev derfra de tre Anaks Sønner: Sesai og Ahiman og Talmai, Anaks Sønner.',
        15: 'Og han drog derfra op til Indbyggerne i Debir; men Debir hed fordum Kirjath-Sefer.',
        16: 'Og Kaleb sagde: Hvo som slaar Kirjath-Sefer og indtager den, ham vil jeg give min Datter Aksa til Hustru.',
        17: 'Saa indtog Othniel, en Søn af Kenas, Kalebs Broder, den; og han gav ham sin Datter Aksa til Hustru.',
        18: 'Og det skete, der hun kom, da tilskyndte hun ham til at begære en Ager af sin Fader, og hun sprang ned af Asenet, og Kaleb sagde til hende: Hvad fattes dig?',
        19: 'Og hun sagde: Giv mig en Velsignelse, thi du gav mig et Land Sønder paa, giv mig og Vandkilder; saa gav han hende de øvre og nedre Vandkilder.',
        20: 'Denne er Judas Børns Stammes Arv efter deres Slægter.',
        21: 'Og disse vare Stæderne ved Enden af Judas Børns Stamme op mod Edoms Landemærke Sønder paa: Kabzeel og Eder og Jagur',
        22: 'og Kina og Dimona og Adada',
        23: 'og Kedes og Hazor og Jithnan,',
        24: 'Sif og Telem og Bealoth',
        25: 'og Hazor-Hadatta og Kirjoth-Hezron, det er Hazor,',
        26: 'Amam og Sema og Molada',
        27: 'og Hazor-Gadda og Hesmon og Beth-Peleth',
        28: 'og Hazor-Sual og Beer-Seba og Bisjothja,',
        29: 'Baala og Jim og Ezem',
        30: 'og Eltholad og Kesil og Horma',
        31: 'og Ziklag og Madmanna og Sansanna',
        32: 'og Lebaoth og Silhim og Ain og Rimmom; i alt ni og tyve Stæder og deres Landsbyer.',
        33: 'I Lavlandet var: Esthaol og Zora og Asna',
        34: 'og Sannoa og En-Gannim, Thappua og Enam,',
        35: 'Jarmuth og Adullam, Soko og Aseka',
        36: 'og Saaraim og Adithaim og Gedera og Gederothaim; fjorten Stæder og deres Landsbyer.',
        37: 'Zenan og Hadasa og Migdal-Gad',
        38: 'og Dilan og Mizpe og Joktheel,',
        39: 'Lakis og Boskath og Eglon',
        40: 'og Kabbon og Lakmas og Kithlis',
        41: 'og Gederoth, Beth-Dagon og Naama og Makkeda; seksten Stæder og deres Landsbyer.',
        42: 'Libna og Ether og Asan',
        43: 'og Jifta og Asna og Nezip',
        44: 'og Keila og Aksib og Maresa; ni Stæder og deres Landsbyer.',
        45: 'Ekron med de tilliggende Stæder og dens Landsbyer;',
        46: 'fra Ekron og til Havet, alle de, som ere ved Siden af Asdod, og deres Landsbyer;',
        47: 'Asdod, med dens tilliggende Stæder og dens Landsbyer; Gaza med dens tilliggende Stæder og dens Landsbyer indtil Ægyptens Bæk og det store Hav og Landemærket derhos.',
        48: 'Men paa Bjerget var: Samir og Jathir og Soko',
        49: 'og Danna og Kirjath Sanna, det er Debir,',
        50: 'og Anab og Esthemo og Anim',
        51: 'og Gosen og Holon og Gilo; elleve Stæder og deres Landsbyer.',
        52: 'Arab og Duma og Esean',
        53: 'og Janum og Beth-Thappua og Afeka',
        54: 'og Humta og Kirjath-Arba, det er Hebron, og Zior; ni Stæder og deres Landsbyer.',
        55: 'Maon, Karmel og Sif og Juta',
        56: 'og Jisreel og Jokdeam og Sanoa,',
        57: 'Kain, Gibea og Timna; ti Stæder og deres Landsbyer.',
        58: 'Halhul, Bethzur og Gedor',
        59: 'og Maarath og Beth-Anoth og Elthekon, seks Stæder og deres Landsbyer.',
        60: 'Kirjath-Baal, det er Kirjath-Jearim, og Rabba; to Stæder og deres Landsbyer.',
        61: 'I Ørken var: Beth-Araba, Middin og Sekaka',
        62: 'og Nibsan og Ir-Melak og En-Gedi; seks Stæder og deres Landsbyer.',
        63: 'Men Jebusiterne, som boede i Jerusalem, dem kunde Judas Børn ikke fordrive; saa boede Jebusiterne tillige med Judas Børn i Jerusalem indtil denne Dag.',
    },
    16: {
        1: 'Og Lodden udkom for Josefs Børn: Fra Jordanen ved Jeriko, ved Vandet fra Jeriko mod Østen, den Ørk, som gaar op fra Jeriko til Bjerget ved Bethel.',
        2: 'Og Landemærket gaar videre fra Bethel til Lus og gaar igennem til Arkiternes Landemærke til Ataroth.',
        3: 'Og det gaar ned mod Vest til Jaflethiternes Landemærke, indtil det nedre Beth-Horons Landemærke og indtil Geser, og dets Udgang er til Havet.',
        4: 'Og dette arvede Josefs Børn, Manasse og Efraim.',
        5: 'Og Efraims Børns Landemærke efter deres Slægter, deres Arvs Landemærke var mod Østen, fra Ataroth-Addar indtil det øvre Beth-Horon.',
        6: 'Og Landemærket gaar i Vesten ud fra Nordsiden af Mikmethath, og Landemærket gaar omkring i Øster til Thaanath-Silo, og det gaar forbi den, Østen for Janoa.',
        7: 'Og det kommer ned fra Janoa til Ataroth og Naara og skyder op mod Jeriko og gaar ud til Jordan.',
        8: 'Fra Thappua gaar Landemærket i Vester til Bækken Kana; og dets Udgang er til Havet; dette er Efraims Børns Stammes Arv efter deres Slægter.',
        9: 'Hertil kom de Stæder, som vare udlagte for Efraims Børn midt iblandt Manasse Børns Arv, alle Stæderne og deres Landsbyer.',
        10: 'Og de fordreve ikke Kananiten, som boede i Geser; men Kananiten boede iblandt Efraim indtil denne Dag og blev en skatskyldig Tjener.',
    },
    17: {
        1: 'Og Lodden faldt for Manasse Stamme, thi han er Josefs førstefødte; for Makir, Manasse førstefødte, Gileads Fader, fordi han var en Krigsmand, derfor blev Gilead og Basan hans.',
        2: 'Men for de øvrige af Manasse Børn iblandt deres Slægter var og falden en Lod, nemlig for Abiesers Børn og for Heleks Børn og for Asriels Børn og for Sekems Børn og for Hefers Børn og for Semidas Børn; disse ere Manasse, Josefs Søns, Børn, de af Mandkøn iblandt deres Slægter.',
        3: 'Men Zelafehad, en Søn af Hefer, en Søn af Gilead, en Søn af Makir, en Søn af Manasse, han havde ikke Sønner, men Døtre; og disse ere hans Døtres Navne: Mahela og Noa, Hogla, Milka og Tirza.',
        4: 'Og de kom frem for Eleasars, Præstens, Ansigt, og for Josvas, Nuns Søns, Ansigt, og for Fyrsternes Ansigt, og sagde: Herren bød Mose, at han skulde give os Arv midt iblandt vore Brødre; og man gav dem Arv efter Herrens Mund, midt iblandt deres Faders Brødre.',
        5: 'Og der faldt ti Parter for Manasse, foruden Gileads Land og Basan, som ligger paa hin Side Jordanen.',
        6: 'Thi Manasse Døtre fik Arv midt iblandt hans Sønner; men Manasse øvrige Børn havde faaet Landet Gilead.',
        7: 'Og Manasse Landemærke var fra Aser til Mikmethath, som ligger lige for Sikem; og Landemærket gaar ud paa den højre Side til Indbyggerne i En-Thappua.',
        8: 'Thappua Land hørte Manasse til; men Thappua ved Manasse Landemærke hørte Efraims Børn til.',
        9: 'Og Landemærket gaar ned til Bækken Kana, Sønden for Bækken; disse Stæder høre Efraim til midt iblandt Manasse Stæder; men Manasse Landemærke er Norden for Bækken, og dets Udgang er ved Havet.',
        10: 'Mod Sønden var Efraims og mod Norden var Manasse Arv, og Havet var hans Landemærke; og de støde op til Aser mod Norden og til Isaskar mod Østen.',
        11: 'Men Manasse havde iblandt Isaskar og iblandt Aser: Beth-Sean med dens tilhørende Stæder og Jibleam med dens tilhørende Stæder og Indbyggerne i Dor med dens tilhørende Stæder og Indbyggerne i En-Dor med dens tilhørende Stæder og Indbyggerne i Thaanak med dens tilhørende Stæder og Indbyggerne i Megiddo med dens tilhørende Stæder, som ere de tre Høje.',
        12: 'Og Manasse Børn kunde ikke indtage disse Stæder, men Kananiten boede roligt i samme Land.',
        13: 'Og det skete, der Israels Børn bleve stærke, da gjorde de Kananiten skatskyldig; men de fordreve ham ikke aldeles.',
        14: 'Og Josefs Børn talede med Josva og sagde: Hvorfor gav du mig ikkun een Lod og een Part til Arv? Jeg er et stort Folk, eftersom Herren har velsignet mig hidindtil.',
        15: 'Og Josva sagde til dem: Dersom du er et stort Folk, da gak op i Skoven og udhug dig der et Stykke i Feresiternes og Kæmpernes Land, efterdi Efraims Bjerg er dig for trangt.',
        16: 'Da sagde Josefs Børn: Dette Bjerg er ikke tilstrækkeligt for os; tilmed er der Jernvogne hos alle Kananiterne, som bo i Dallandet, hos dem, som bo i Beth-Sean med dens tilliggende Stæder, og hos dem, som bo i Jisreels Dal.',
        17: 'Og Josva sagde til Josefs Hus, til Efraim og til Manasse, sigende: Du er et stort Folk, og du har stor Styrke, du skal ikke have een Lod blot.',
        18: 'Thi et Bjerg skal høre dig til, og fordi det er en Skov, da skal du hugge den af, og dens Udgange skulle høre dig til; thi du skal fordrive Kananiten, enddog han har Jernvogne, enddog han er stærk.',
    },
    18: {
        1: 'Og al Israels Børns Menighed samledes i Silo og satte der Forsamlingens Paulun, og Landet var dem underlagt.',
        2: 'Og der var endnu syv Stammer tilovers af Israels Børn, som ikke havde delt deres Arv.',
        3: 'Og Josva sagde til Israels Børn: Hvor længe ere I saa efterladne med at komme til at eje Landet, som Herren, eders Fædres Gud, har givet eder?',
        4: 'Vælger eder tre Mænd for hver Stamme, saa vil jeg udsende dem, at de kunne gøre sig rede og gaa igennem Landet og beskrive det for at kunne bestemme deres Arv, og de skulle komme til mig igen.',
        5: 'Og de skulle dele det i syv Dele; Juda skal blive i sit Landemærke mod Sønden; og Josefs Hus, de skulle blive i deres Landemærke mod Norden.',
        6: 'Men I skulle beskrive Landet og dele det i syv Dele og føre Beskrivelsen herhid til mig; saa vil jeg her kaste Lod for eder, for Herrens vor Guds Ansigt.',
        7: 'Thi Leviterne have ingen Del midt iblandt eder, men Herrens Præstedømme er deres Arv; og Gad og Ruben og den halve Manasse Stamme have taget deres Arv paa hin Side Jordanen mod Østen, som Mose, Herrens Tjener, gav dem.',
        8: 'Da gjorde Mændene sig rede og gik; og Josva befalede dem, som gik hen at beskrive Landet, og sagde: Gaar og vandrer om i Landet og beskriver det og kommer tilbage til mig, saa vil jeg her kaste Lod for eder, for Herrens Ansigt, i Silo.',
        9: 'Saa gik Mændene hen og gik igennem Landet og beskreve det i en Bog efter Stæderne og delte det i syv Dele; og de kom tilbage til Josva til Lejren i Silo.',
        10: 'Saa kastede Josva Lod for dem i Silo, for Herrens Ansigt; og Josva delte der Landet for Israels Børn, efter deres Afdelinger.',
        11: 'Og Benjamins Børns Stammes Lod kom ud efter deres Slægter, og Landemærket for deres Lod gik ud imellem Judas Børn og imellem Josefs Børn.',
        12: 'Og deres Landemærke paa den nordre Side var fra Jordanen; Landemærket gaar op til Nordsiden af Jeriko og gaar op til Bjerget imod Vesten, og Udgangene derpaa vare mod Ørken ved Beth-Aven.',
        13: 'Og Landemærket gaar derfra over til Lus, til den søndre Side af Lus, det er Bethel; og Landemærket gaar ned til Atharoth-Addar over Bjerget, som ligger Sønden for det nedre Beth-Horon.',
        14: 'Og Landemærket gaar videre og bøjer sig om den venstre Side mod Sønden, fra Bjerget, som ligger tværs over for Beth-Horon mod Sønden, og Udgangen derpaa er til Kirjath-Baal, det er Kirjath-Jearim, Judas Børns Stad; dette er den vestre Side.',
        15: 'Men Sydsiden er fra det yderste af Kirjath-Jearim; og Landemærket gaar ud fra Vesten, og det gaar ud til Nefthoas Vandkilde.',
        16: 'Og Landemærket gaar ned til Enden af Bjerget, som ligger tværs over for Hinnoms Søns Dal, og som er i Refaims Dal mod Norden; og det gaar ned til Hinnoms Dal, mod den søndre Side af Jebus, og gaar ned til En-Rogel.',
        17: 'Og det bøjer sig fra Norden og gaar ud til En-Semes og gaar ud til Geliloth, som ligger tværs over for Opgangen til Adummim, og gaar ned til Bohans, Rubens Søns, Sten.',
        18: 'Og det gaar om til Siden tværs over for Araba, mod Norden; og det gaar ned til Araba.',
        19: 'Og Landemærket gaar om til Nordsiden af Beth-Hogla, og Landemærkets Udgang er ved den nordlige Odde af Salthavet, ved Jordanens Udløb mod Sønden; dette er det søndre Landemærke.',
        20: 'Men Jordanen sætter Grænse derfor mod den østre Side; dette er Benjamins Børns Arv i deres Landemærker rundt omkring efter deres Slægter.',
        21: 'Og Benjamins Børns Stammes Stæder efter deres Slægter, vare: Jeriko og Beth-Hogla og Emek-Keziz',
        22: 'og Beth-Araba og Zemarajim og Bethel',
        23: 'og Avim og Para og Ofra',
        24: 'og Kefar-Ammonai og Ofnai og Geba; tolv Stæder og deres Landsbyer.',
        25: 'Gibeon og Rama og Beeroth',
        26: 'og Mizpe og Kefira og Moza',
        27: 'og Rekem og Jirpeel og Tharala',
        28: 'og Zela, Elef og Jebusi, det er Jerusalem, Gibeath, Kirjath; fjorten Stæder og deres Landsbyer; dette er Benjamins Børns Arv, efter deres Slægter.',
    },
    19: {
        1: 'Og den anden Lod kom ud for Simeon, for Simeons Børns Stamme, efter deres Slægter; og deres Arv laa midt i Judas Børns Arv.',
        2: 'Og til deres Arv hørte: Beersaba og Seba og Molada,',
        3: 'og Hazar-Sual og Bala og Ezem,',
        4: 'og El-Tholad og Bethul og Horma,',
        5: 'og Ziklag og Beth-Marcaboth og Hazar-Susa,',
        6: 'og Beth-Lebaoth og Saruhen; tretten Stæder og deres Landsbyer.',
        7: 'Ajin, Rimmon og Ether og Asan; fire Stæder og deres Landsbyer;',
        8: 'og alle de Landsbyer, som ligge rundt omkring disse Stæder indtil Baalath-Beer, det er Ramath mod Sønden; denne er Simeons Børns Stammes Arv efter deres Slægter.',
        9: 'Thi Simeons Børns Arv er af Judas Børns Part; fordi Judas Børns Del var dem for stor, derfor arvede Simeons Børn midt i disses Arv.',
        10: 'Og den tredje Lod kom ud for Sebulons Børn efter deres Slægter, og Landemærket paa deres Arv var indtil Sarid.',
        11: 'Og deres Landemærke gaar op mod Vest og til Marala og støder op til Dabbaseth og støder op til Bækken, som er lige for Jokneam.',
        12: 'Og det vender om fra Sarid mod Østen, mod Solens Opgang, ved Kisloth-Thabors Landemærke, og gaar ud til Dabrath og gaar op til Jafia.',
        13: 'Og det gaar derfra over mod Østen, mod Solens Opgang, til Githa-Hefer, Eth-Kazin, og gaar ud mod Rimmon-Hammethoar, til Nea.',
        14: 'Og Landemærket gaar omkring den mod Nord til Hannathon; og dets Udgang er i Jiftha-Els Dal.',
        15: 'Dertil fik de Kattath og Nahalal og Simron og Jidala og Bethlehem; tolv Stæder og deres Landsbyer.',
        16: 'Denne er Sebulons Børns Arv efter deres Slægter, disse Stæder og deres Landsbyer.',
        17: 'Den fjerde Lod kom ud for Isaskar, for Isaskars Børn efter deres Slægter.',
        18: 'Og deres Landemærke var: Jisreela og Kesulloth og Sunem',
        19: 'og Hafarajim og Skion og Anaharath',
        20: 'og Rabbith og Kisjon og Ebez',
        21: 'og Remeth og En-Gannim og En-Hadda og Beth-Pazzez.',
        22: 'Og Landemærket støder op til Thabor og Sahazim og Beth-Semes, og deres Landemærkes Udgang er Jordanen; seksten Stæder og deres Landsbyer.',
        23: 'Denne er Isaskars Børns Stammes Arv, efter deres Slægter, Stæderne og deres Landsbyer.',
        24: 'Og den femte Lod kom ud for Asers Børns Stamme, efter deres Slægter.',
        25: 'Og deres Landemærke var: Helkath og Hali og Beten og Aksaf',
        26: 'og Allammelek og Amead og Miseal og støder op til Karmel mod Vesten og til Sihor-Libnath',
        27: 'og vender om mod Solens Opgang til Beth-Dagon og støder op til Sebulon og til Jeftha-Els Dal, Nord om Beth-Emek og Negiel, og gaar ud til Kabul, paa den venstre Side,',
        28: 'og Ebron og Rehob og Hammon og Kana, indtil det store Zidon.',
        29: 'Og Landemærket vender om mod Rama og indtil den faste Stad Tyrus, og Landemærket vender om til Hosa, og dets Udgang er ved Havet og strækker sig efter Strøget mod Aksib;',
        30: 'og Umma og Afek og Rehob; to og tyve Stæder og deres Landsbyer.',
        31: 'Denne er Asers Børns Stammes Arv, efter deres Slægter, disse Stæder og deres Landsbyer.',
        32: 'Den sjette Lod kom ud for Nafthali Børn, for Nafthali Børn efter deres Slægter.',
        33: 'Og deres Landemærke er fra Helef, fra Egen i Zaanannim og Adami-Nekeb og Jabneel indtil Lakkum, og Udgangen derpaa er Jordanen.',
        34: 'Og Landemærket vender sig mod Vesten til Asnoth-Thabor og gaar ud derfra til Hukok og støder op til Sebulon mod Sønden og støder til Aser mod Vesten og til Juda ved Jordanen, mod Solens Opgang.',
        35: 'Og der er faste Stæder: Ziddim, Zer og Hamath, Rakkath og Kinnereth',
        36: 'og Adama og Rama og Hazor',
        37: 'og Kedes og Edrei og En-Hazor',
        38: 'og Jiron og Migdal-El, Horem og Beth-Anath og Beth-Semes; nitten Stæder og deres Landsbyer.',
        39: 'Denne er Nafthali Børns Stammes Arv efter deres Slægter, Stæderne og deres Landsbyer.',
        40: 'For Dans Børns Stamme, efter deres Slægter, kom den syvende Lod ud.',
        41: 'Og deres Arvs Landemærke var: Zora og Esthaol og Ir-Semes',
        42: 'og Saalabbin og Ajalon og Jithla',
        43: 'og Elon og Thimnata og Ekron',
        44: 'og Eltheke og Gibbethon og Baalath',
        45: 'og Jehud og Bne-Berak og Gath-Rimmon',
        46: 'og Me-Jarkon og Rakkon med det Landemærke tværs over for Jafo.',
        47: 'Og Dans Børns Landemærke udkom for lidet for dem; derfor droge Dans Børn op og strede mod Lesem og indtoge den og sloge den med skarpe Sværd og toge den til Eje og boede i den, og de kaldte Lesem Dan, efter Dans deres Faders Navn.',
        48: 'Denne er Dans Børns Stammes Arv, efter deres Slægter, disse Stæder og deres Landsbyer.',
        49: 'Og de bleve færdige med at dele Landet til Arv efter deres Landemærker; og Israels Børn gave Josva, Nuns Søn, Arv midt iblandt sig.',
        50: 'Efter Herrens Mund gave de ham den Stad, som han begærede, nemlig Thimnath-Sera, paa Efraims Bjerg; og han byggede Staden op og boede i den.',
        51: 'Disse ere de Arvedele, som Eleasar, Præsten, og Josva, Nuns Søn, og Øversterne for Fædrenehusene iblandt Israels Børns Stammer uddelte til Arv ved Lod i Silo, for Herrens Ansigt, for Forsamlingens Pauluns Dør; og de bleve færdige med at dele Landet.',
    },
    20: {
        1: 'Og Herren talede til Josva og sagde:',
        2: 'Tal til Israels Børn, sigende: Afgiver for eder de Tilflugtsstæder, om hvilke jeg talede til eder ved Mose,',
        3: 'at en Manddraber, som af Vaade, uforsætlig slaar en Person ihjel, kan fly derhen, og at de kunne være eder til Tilflugt for Blodhævneren.',
        4: 'Og han skal fly til en af disse Stæder, og han skal staa uden for Indgangen til Stadens Port og tale sine Ord for de Ældstes Øren af samme Stad, saa skulle de tage ham ind i Staden til sig og give ham et Sted, hvor han kan bo hos dem.',
        5: 'Og naar Blodhævneren forfølger ham, da skulle de ikke overantvorde Manddraberen i hans Haand, efterdi han slog sin Næste uforsætlig og ikke tilforn var hans Fjende.',
        6: 'Saa skal han bo i den samme Stad, indtil han har staaet for Menighedens Ansigt for Retten, indtil den Ypperstepræst, som var i de Dage, er død; da maa Manddraberen vende tilbage og komme til sin Stad og til sit Hus, til Staden, hvorfra han flyede.',
        7: 'Saa helligede de Kedes i Galilæa paa Nafthali Bjerg og Sikem paa Efraims Bjerg og Kirjath-Arba, det er Hebron, paa Judas Bjerg.',
        8: 'Og paa hin Side Jordanen ved Jeriko, mod Østen, afgave de Bezer i Ørken paa Sletten af Rubens gtamme og Ramoth i Gilead af Gads Stamme og Golan i Basan af Manasse Stamme.',
        9: 'Disse vare de Stæder, som vare beskikkede for alle Israels Børn og for den fremmede, som var fremmed midt iblandt dem, at hver den, som slog en Person af Vaade, maatte fly derhen, at han ikke skulde dø ved Blodhævnerens Haand, inden han havde staaet for Menighedens Ansigt.',
    },
    21: {
        1: 'Da gik Øversterne for Leviternes Fædrenehuse frem til Eleasar, Præsten, og til Josva, Nuns Søn, og til Øversterne for Fædrenehusene blandt Israels Børns Stammer,',
        2: 'og de talede til dem i Silo i Kanaans Land og sagde: Herren bød ved Mose, at man skulde give os Stæder at bo udi og deres Marker til vort Kvæg.',
        3: 'Da gave Israels Børn Leviterne af deres Arv, efter Herrens Mund, disse Stæder og deres Marker.',
        4: 'Og Lodden kom ud for Kahathiternes Slægter; og Arons, Præstens Børn af Leviterne fik af Judas Stamme og Simeons Stamme og af Benjamins Stamme ved Lodkastningen tretten Stæder.',
        5: 'Men de øvrige Kahaths Børn fik af Efraims Stammes Slægter og af Dans Stamme og af den halve Manasse Stamme ved Lodkastningen ti Stæder.',
        6: 'Og Gersons Børn fik af Isaskars Stammes Slægter og af Asers Stamme og af Nafthali Stamme og af den halve Manasse Stamme i Basan ved Lodkastningen tretten Stæder.',
        7: 'Merari Børn efter deres Slægter fik af Rubens Stamme og af Gads Stamme og af Sebulons Stamme tolv Stæder.',
        8: 'Saa gave Israels Børn Leviterne ved Lodkastning disse Stæder og deres Marker, ligesom Herren havde budet ved Mose.',
        9: 'Og de gave dem af Judas Børns Stamme og af Simeons Børns Stamme disse Stæder, som man nævnede ved Navn.',
        10: 'Og Arons Børn af Kahathiternes Slægter, af Levi Børn, fik disse — thi den første Lod var deres —',
        11: 'og de gave ham Arba, Anoks Faders Stad, det er Hebron paa Judas Bjerg, og dens Agerland rundt omkring den.',
        12: 'Og Stadens Mark og dens Landsbyer gave de Kaleb, Jefunne Søn, til hans Ejendom.',
        13: 'Og de gave Arons, Præstens Børn Tilflugtsstaden for Manddrabere Hebron og dens Marker og Libna og dens Marker',
        14: 'og Jathir og dens Marker og Esthemoa og dens Marker',
        15: 'og Holon og dens Marker og Debir og dens Marker',
        16: 'og Ajin og dens Marker og Jutta og dens Marker og Beth-Semes og dens Marker, ni Stæder af disse to Stammer;',
        17: 'men af Benjamins Stamme: Gibeon og dens Marker, Geba og dens Marker,',
        18: 'Anathoth og dens Marker og Almon og dens Marker, fire Stæder.',
        19: 'Alle Præsternes, Arons Børns, Stæder vare tretten Stæder og deres Marker.',
        20: 'Men Kahaths Børns Slægter, af Leviterne, de andre af Kahaths Børn, fik de Stæder, som hørte til deres Lod, af Efraims Stamme.',
        21: 'Og de gave dem Tilflugtsstaden for Manddrabere Sikem og dens Marker, paa Efraims Bjerg, og Geser og dens Marker',
        22: 'og Kibzaim og dens Marker og Beth-Horon og dens Marker, fire Stæder;',
        23: 'og af Dans Stamme: Eltheke og dens Marker, Gibbethon og dens Marker,',
        24: 'Ajalon og dens Marker, Gath-Rimmon og dens Marker, fire Stæder;',
        25: 'og af den halve Manasse Stamme: Thaanak og dens Marker og Gath-Rimmon og dens Marker, to Stæder.',
        26: 'Alle Stæder vare ti og deres Marker for de andre Kahaths Børns Slægter.',
        27: 'Og Gersons Børn af Leviternes Slægter gave de af den halve Manasse Stamme: Tilflugtsstaden for Manddrabere Golan i Basan og dens Marker og Beesthera og dens Marker, to Stæder;',
        28: 'og af Isaskars Stamme: Kisjon og dens Marker, Dabrath og dens Marker,',
        29: 'Jarmuth og dens Marker, En-Gannim og dens Marker, fire Stæder;',
        30: 'og af Asers Stamme: Miseal og dens Marker, Abdon og dens Marker,',
        31: 'Helkath og dens Marker, og Rehob og dens Marker, fire Stæder;',
        32: 'og af Nafthali Stamme: Tilflugtsstaden for Manddrabere Kedes i Galilæa og dens Marker og Hamoth-Dor og dens Marker og Karthan og dens Marker, tre Stæder;',
        33: 'alle Gersoniternes Stæder efter deres Slægter vare tretten Stæder og deres Marker.',
        34: 'Men til Merari Børns Slægter, som vare de øvrige af Leviterne, gave de af Sebulons Stamme: Jokneam og dens Marker, Kartha og dens Marker,',
        35: 'Dimna og dens Marker, Nahalal og dens Marker, fire Stæder;',
        36: 'og af Rubens Stamme: Bezer og dens Marker og Jahza og dens Marker,',
        37: 'Kedemoth og dens Marker og Mefaath og dens Marker, fire Stæder;',
        38: 'og af Gads Stamme: Tilflugtsstaden for Manddrabere Ramoth i Gilead og dens Marker og Mahanajim og dens Marker,',
        39: 'Hesbon og dens Marker, Jaeser og dens Marker; alle de Stæder vare fire.',
        40: 'Alle disse vare Merari Børns Stæder efter deres Slægter, de øvrige af Leviternes Slægter, og deres Lod var tolv Stæder.',
        41: 'Alle Leviternes Stæder midt i Israels Børns Ejendom, vare otte og fyrretyve Stæder og deres Marker.',
        42: 'Disse Stæder laa hver for sig, med deres Marker trindt omkring; saaledes havde det sig med alle disse.',
        43: 'Og Herren gav Israel alt det Land, som han havde svoret at give deres Fædre, og de toge det i Eje og boede derudi.',
        44: 'Og Herren gav dem Rolighed trindt omkring, efter alt det, som han havde svoret deres Fædre; og ingen bestod for deres Ansigt af alle deres Fjender; Herren gav alle deres Fjender i deres Haand.',
        45: 'Der blev ikke et Ord til intet af alle de gode Ord, som Herren havde talet til Israels Hus, det opfyldtes alt sammen.',
    },
    22: {
        1: 'Da kaldte Josva ad Rubeniterne og ad Gaditerne og ad den halve Manasse Stamme,',
        2: 'og han sagde til dem: I have holdt alt det, som Mose, Herrens Tjener, bød eder, og I have hørt min Røst i alt det, som jeg har budet eder.',
        3: 'I have ikke forladt eders Brødre i disse mange Aar indtil denne Dag; men I have taget Vare paa, hvad I skulle varetage, Herrens, eders Guds, Bud.',
        4: 'Og nu har Herren eders Gud skaffet eders Brødre Rolighed, som han havde tilsagt dem; saa vender eder nu og drager til eders Telte til eders Ejendoms Land, som Mose, Herrens Tjener, gav eder paa hin Side Jordanen.',
        5: 'Alene tager Vare paa at gøre det Bud og den Lov, som Mose, Herrens Tjener, bød eder, at elske Herren eders Gud og at vandre i alle hans Veje og at holde hans Bud og at hænge ved ham og at tjene ham af eders ganske Hjerte og af eders ganske Sjæl.',
        6: 'Saa velsignede Josva dem og lod dem fare, og de gik til deres Telte.',
        7: 'Og Mose havde givet den halve Manasse Stamme Arv i Basan, og Halvdelen deraf gav Josva Arv med deres Brødre paa denne Side Jordanen mod Vesten. Og tilmed der Josva lod dem fare til deres Telte og havde velsignet dem,',
        8: 'da sagde han til dem saalunde: Drager tilbage til eders Telte med meget Gods og med saare meget Kvæg, med Sølv og med Guld og med Kobber og med Jern og med saare mange Klæder, deler Byttet fra eders Fjender med eders Brødre!',
        9: 'Saa vendte Rubens Børn og Gads Børn og den halve Manasse Stamme tilbage og gik fra Israels Børn fra Silo, som er i Kanaans Land, for at gaa til Gileads Land, til deres Ejendoms Land, i hvilket de havde taget Arv efter Herrens Befaling ved Mose.',
        10: 'Og der de kom til Geliloth, som ligger i Kanaans Land, ved Jordanen, da byggede Rubens Børn og Gads Børn og den halve Manasse Stamme der et Alter ved Jordanen, et Alter stort af Anseelse.',
        11: 'Og Israels Børn hørte sige: Se, Rubens Børn og Gads Børn og den halve Manasse Stamme have bygget et Alter foran i Kanaans Land, i Geliloth ved Jordan, over for Israels Børn.',
        12: 'Der Israels Børn hørte det, da forsamlede sig al Israels Børns Menighed i Silo, til at drage op imod dem til Strid.',
        13: 'Saa sendte Israels Børn til Rubens Børn og til Gads Børn og til den halve Manasse Stamme, til Gileads Land, Pinehas, Præsten Eleasars Søn,',
        14: 'og ti Fyrster med ham, een Fyrste, hver for et Fædrenehus, af hver af Israels Stammer; og hver af dem var Øverste for deres Fædres Hus, for Israels Tusinder.',
        15: 'Og der de kom til Rubens Børn og til Gads Børn og til den halve Manasse Stamme, til Gileads Land, da talede de med dem og sagde:',
        16: 'Saa siger al Herrens Menighed: Hvad er denne for en Troløshed, som I have vist mod Israels Gud, i Dag at vende eder bort fra Herren, idet I bygge eder et Alter, saa at I ville i Dag være genstridige mod Herren?',
        17: 'Er Misgerningen ved Peor os for liden, fra hvilken vi ikke have renset os indtil denne Dag, og Plagen kom dog over Herrens Menighed?',
        18: 'Og I vende eder i Dag bort fra Herren! og det sker, om I i Dag ere genstridige imod Herren, at han herefter bliver vred paa al Israels Menighed.',
        19: 'Men dersom eders Ejendoms Land er urent, da kommer over til Herrens Ejendoms Land, hvor Herrens Tabernakel boer, og tager Arv midt iblandt os; og værer ikke genstridige imod Herren, og værer ikke genstridige imod os, saa at I bygge eder et Alter foruden Herrens, vor Guds, Alter.',
        20: 'Mon ikke Akan, Seras Søn, forgreb sig saare paa det bandlyste? og der kom en Vrede over al Israels Menighed, og denne ene Mand, han var ikke den eneste, som omkom for sin Misgerning.',
        21: 'Da svarede Rubens Børn og Gads Børn og den halve Manasse Stamme, og de sagde til de Øverste for Israels Tusinder:',
        22: 'Den stærke, Gud, Herren, den stærke, Gud, Herren, han ved det, og Israel skal vide det: Ej er det Genstridighed, og ej er det Overtrædelse imod Herren — saa frelse du os ikke paa denne Dag! —',
        23: 'at vi vilde bygge os et Alter, for at vende os bort fra Herren; og ej er det for at ofre Brændoffer derpaa eller Madoffer, og ej er det for at gøre Takoffer derpaa — saa hjemsøge Herren det selv! —',
        24: 'men vi gjorde det af Omhyggelighed, for den Sags Skyld, at vi sagde: Eders Børn maatte ellers herefter sige til vore Børn: Hvad have I at gøre med Herren, Israels Gud?',
        25: 'Herren har jo sat Jordanen til Landemærke imellem os og imellem eder, I Rubens Børn og Gads Børn, I have ingen Del i Herren: Saa maatte eders Børn bringe vore Børn til at høre op med at frygte Herren.',
        26: 'Derfor sagde vi: Lader os dog gøre dette, at bygge et Alter, ikke til Brændoffer og ej til Slagtoffer;',
        27: 'men det skal være et Vidne imellem os og imellem eder og imellem vore Efterkommere efter os, at vi betjene Herrens Tjeneste for hans Ansigt med vore Brændofre og med vore Slagtofre og med vore Takofre, og at eders Børn ikke herefter skulle sige til vore Børn: I have ingen Del i Herren.',
        28: 'Derfor sagde vi: Naar det sker, at de sige sligt til os eller til vore Efterkommere herefter, da ville vi sige: Ser den Lignelse af Herrens Alter, som vore Fædre gjorde ikke til Brændoffer og ikke til Slagtoffer, men til et Vidne imellem os og imellem Eder.',
        29: 'Dette skal være langt fra os at være genstridige mod Herren og at vende os i Dag bort fra Herren, til at bygge et Alter til Brændoffer, til Madoffer og til Slagtoffer, foruden Herren vor Guds Alter, som er foran hans Tabernakel.',
        30: 'Der Pinehas, Præsten, og Menighedens Fyrster og Øversterne over Israels Tusinder, som vare med ham, hørte de Ord, som Rubens Børn og Gads Børn og Manasse Børn sagde, da var det godt for deres Øjne.',
        31: 'Og Pinehas, Præsten Eleasars Søn, sagde til Rubens Børn og til Gads Børn og til Manasse Børn: I Dag kende vi, at Herren er midt iblandt os, idet I ikke have vist en saadan Troløshed imod Herren, da I have reddet Israels Børn af Herrens Haand.',
        32: 'Da drog Pinehas, Præsten Eleasars Søn, og Fyrsterne fra Rubens Børn og fra Gads Børn fra Gileads Land til Kanaans Land igen, til Israels Børn; og de bragte dem Svar igen.',
        33: 'Og det Ord var godt for Israels Børns Øjne, og Israels Børn lovede Gud, og de sagde ikke, at de vilde drage op imod dem til Strid for at ødelægge det Land, som Rubens Børn og Gads Børn boede udi.',
        34: 'Og Rubens Børn og Gads Børn gave Alteret det Navn: „det er Vidne imellem os, at Herren er Gud‟.',
    },
    23: {
        1: 'Og det skete mange Aar efter, at Herren havde skaffet Israel Rolighed for alle deres Fjender trindt omkring, og Josva var gammel, var kommen til Aars:',
        2: 'Da kaldte Josva ad alt Israel, ad deres Ældste og deres Øverster og deres Dommere og deres Fogeder, og han sagde til dem: Jeg er gammel, jeg er kommen til Aars.',
        3: 'Og I have set alt, hvad Herren eders Gud har gjort ved alle disse Folk for eders Ansigt; thi Herren eders Gud, han er den, som har stridt for eder.',
        4: 'Ser, jeg har ladet disse Folk, som ere overblevne, tilfalde eder til Arv for eders Stammer, fra Jordanen af, tillige med alle de Folk, som jeg har udryddet, og indtil det store Hav mod Solens Nedgang.',
        5: 'Og Herren eders Gud, han skal udstøde dem fra eders Ansigt, og han skal fordrive dem fra at være for eders Ansigt; og I skulle eje deres Land, som Herren eders Gud har tilsagt eder.',
        6: 'Saa værer saare stærke til at holde og at gøre alt det, som er skrevet i Mose Lovbog, saa at I ikke vige derfra til højre eller venstre Side,',
        7: 'at I ikke komme iblandt disse Folk, som ere tilovers hos eder, og I ikke nævne eller lade sværge ved deres Guders Navn og ikke tjene dem og ikke tilbede dem;',
        8: 'men I skulle hænge fast ved Herren eders Gud, som I have gjort indtil denne Dag;',
        9: 'thi Herren har fordrevet store og stærke Folk fra eders Ansigt; og ingen har bestaaet for eders Ansigt indtil denne Dag.',
        10: 'Een Mand af eder skal forfølge tusinde; thi Herren eders Gud, han er den, som strider for eder, som han har tilsagt Eder.',
        11: 'Derfor tager nøje Vare paa eders Sjæle, at I elske Herren, eders Gud.',
        12: 'Thi dersom I vende eder bort og hænge ved disse øvrige Hedninger, disse, som ere tilovers hos eder, og I gøre Svogerskab med dem, og I komme iblandt dem, og de iblandt eder:',
        13: 'Da skulle I visseligen vide, at Herren eders Gud skal ikke ydermere fordrive disse Folk fra eders Ansigt; men de skulle blive eder til en Fælde og til en Snare og til en Svøbe paa eders Sider og til Brodde i eders Øjne, indtil I omkomme af dette gode Land, som Herren eders Gud har givet eder.',
        14: 'Og se, jeg gaar i Dag al Jordens Gang; og I skulle vide i eders ganske Hjerte og i eders ganske Sjæl, at ikke eet Ord er faldet af alle de gode Ord, som Herren eders Gud har talet over eder, at de jo alle ere opfyldte for eder, der faldt ikke et Ord af dem.',
        15: 'Og det skal ske, at ligesom alle de gode Ord ere opfyldte over eder, som Herren eders Gud har talet til eder, saaledes skal Herren lade alle de onde Ord opfyldes over eder, indtil han udrydder eder af dette gode Land, som Herren eders Gud gav eder.',
        16: 'Naar I overtræde Herrens, eders Guds Pagt, som han bød eder, og gaa og tjene andre Guder og tilbede dem, da skal Herrens Vrede optændes imod eder, og I skulle snart omkomme af det gode Land, som han har givet eder.',
    },
    24: {
        1: 'Og Josva samlede alle Israels Stammer til Sikem, og han sammenkaldte Israels Ældste og deres Øverster og deres Dommere og deres Fogeder, og de stillede sig for Guds Ansigt.',
        2: 'Da sagde Josva til alt Folket: Saa siger Herren, Israels Gud: Eders Fædre boede fordum paa hin Side Floden, Thara, Abrahams Fader og Nakors Fader, og de tjente andre Guder.',
        3: 'Og jeg tog eders Fader Abraham fra hin Side Floden og lod ham vandre om i hele Kanaans Land, og jeg formerede hans Sæd og gav ham Isak.',
        4: 'Og Isak gav jeg Jakob og Esau; og jeg gav Esau Sejrs Bjerg til Eje, men Jakob og hans Børn droge ned til Ægypten.',
        5: 'Da sendte jeg Mose og Aron og slog Ægypterne, ligesom jeg gjorde midt iblandt dem; og derefter førte jeg eder ud.',
        6: 'Og jeg udførte eders Fædre af Ægypten, og I kom til Havet; og Ægypterne forfulgte eders Fædre med Vogne og med Ryttere til det røde Hav.',
        7: 'Da raabte de til Herren, og han satte et Mørke imellem eder og imellem Ægypterne og lod Havet komme over dem, og det skjulte dem, og eders Øjne have set det, som jeg gjorde i Ægypten; og I bleve i Ørken mange Aar.',
        8: 'Og jeg førte eder ind i Amoriternes Land, som boede paa hin Side Jordanen, og de strede mod eder; og jeg gav dem i eders Haand, saa at I indtoge deres Land til Ejendom, og jeg ødelagde dem for eders Ansigt.',
        9: 'Da gjorde Balak, Zippors Søn, Moabs Konge, sig rede og stred mod Israel, og han sendte hen og kaldte Bileam, Beors Søn, til at forbande eder.',
        10: 'Men jeg vilde ikke høre Bileam; og han velsignede eder, og jeg reddede eder af hans Haand.',
        11: 'Og der I gik over Jordanen og kom til Jeriko, da strede Mændene af Jeriko, Amoriterne og Feresiterne og Kananiterne og Hethiterne og Girgasiterne og Heviterne og Jebusiterne imod eder; men jeg gav dem i eders Haand.',
        12: 'Og jeg sendte foran eder Gedehamse, som uddreve dem fra eders Ansigt, saa vel som de to Amoriters Konger, ikke med dit Sværd, ej heller med din Bue.',
        13: 'Og jeg gav eder et Land, paa hvilket du ikke har arbejdet, og Stæder, som I ikke have bygget, og I bo udi dem; af Vingaarde og af Oliegaarde, som I ikke have plantet, æde I.',
        14: 'Saa frygter nu Herren og tjener ham i Oprigtighed og i Sandhed, og borttager de Guder, som eders Fædre tjente paa hin Side Floden og i Ægypten, og tjener Herren!',
        15: 'Og om det mishager eder at tjene Herren, saa udvælger eder i Dag, hvem I ville tjene, enten de Guder, som eders Fædre, der vare paa hin Side Floden, tjente, eller Amoriternes Guder, i hvis Land I bo; men jeg og mit Hus, vi ville tjene Herren.',
        16: 'Da svarede Folket og sagde: Det være langt fra os at forlade Herren for at tjene andre Guder.',
        17: 'Thi Herren vor Gud, han er den, som førte os og vore Fædre op af Ægyptens Land, af Trælles Hus, og som gjorde disse store Tegn for vore Øjne og bevarede os paa al den Vej, hvorpaa vi gik, og iblandt alle de Folk, vi have gaaet midt igennem.',
        18: 'Og Herren har uddrevet alle Folkene, endog Amoriten, som boede i Landet, fra vort Ansigt; ogsaa vi ville tjene Herren, thi han er vor Gud.',
        19: 'Og Josva sagde til Folket: I kunne ikke tjene Herren, thi han er en hellig Gud, han er en nidkær Gud, han skal ikke bære over med eders Overtrædelser og eders Synder.',
        20: 'Naar I forlade Herren og tjene fremmede Guder, da skal han vende om og gøre eder ondt og fortære eder, efter at han har gjort eder godt.',
        21: 'Og Folket sagde til Josva: Ingenlunde! men vi ville tjene Herren.',
        22: 'Da sagde Josva til Folket: I ere selv Vidner imod eder, at I have udvalgt eder Herren til at tjene ham; og de sagde: Vi ere Vidner.',
        23: 'Saa borttager nu de fremmede Guder, som ere midt iblandt eder, og bøjer eders Hjerter til Herren, Israels Gud.',
        24: 'Og Folket sagde til Josva: Vi ville tjene Herren vor Gud, og vi ville høre hans Røst.',
        25: 'Saa gjorde Josva paa den samme Dag en Pagt med Folket, og han lagde dem Lov og Ret for i Sikem.',
        26: 'Og Josva skrev disse Ord i Guds Lovbog; og han tog en stor Sten og lod den oprejse der under Egen, som var ved Herrens Helligdom.',
        27: 'Og Josva sagde til alt Folket: Se, denne Sten skal være til Vidnesbyrd imod os, thi den har hørt alle Herrens Ord, som han har talet med os; ja, den skal være til Vidnesbyrd imod eder, at I ikke skulle fornægte eders Gud.',
        28: 'Saa lod Josva Folket fare, hver til sin Arv.',
        29: 'Og det skete efter disse Handler, da døde Josva, Nuns Søn, Herrens Tjener, hundrede og ti Aar gammel.',
        30: 'Og de begrove ham i hans Arvs Landemærke i Thimnath-Sera, som ligger paa Efraims Bjerg, Norden for Gaas Bjerg.',
        31: 'Og Israel tjente Herren, saa længe Josva levede, og saa længe de Ældste levede, som levede længe efter Josva, og som kendte al Herrens Gerning, hvilken han havde gjort mod Israel.',
        32: 'Og Josefs Ben, som Israels Børn havde ført op af Ægypten, begrove de i Sikem, paa den Agers Del, som Jakob havde købt af Hemors, Sikems Faders, Børn for hundrede Penninge; og de bleve Josefs Børn til Arv.',
        33: 'Og Eleasar, Arons Søn, døde, og de begrove ham i Gibea, som hørte hans Søn Pinehas til og var given ham paa Efraims Bjerg.',
    },
}
